# GPU tracking
# ---------------------------------------------------------------------------

def _get_available_gpu_count() -> int:
    """Detect number of GPUs via nvidia-smi."""
    try:
        out = subprocess.run(
            ["nvidia-smi", "--query-gpu=index", "--format=csv,noheader"],
            capture_output=True, text=True, timeout=10,
        )
        return len(out.stdout.strip().splitlines())
    except Exception:
        return 0


def _get_free_gpus(all_gpus: list[int], running_jobs: list[Job]) -> list[int]:
    """Return GPU indices not currently assigned to running jobs."""
    used = set()
    for j in running_jobs:
        if j.state == "running" and j.gpus and j.pid and _job_alive(j.pid):
            for g in j.gpus.split(","):
                used.add(int(g))
    return [g for g in all_gpus if g not in used]


def _query_gpu_memory_used() -> dict[int, int]:
    """Return current GPU memory usage in MiB keyed by GPU index."""
    try:
        out = subprocess.run(
            ["nvidia-smi", "--query-gpu=index,memory.used", "--format=csv,noheader,nounits"],
            capture_output=True,
            text=True,
            timeout=10,
            check=False,
        )
    except Exception:
        return {}
    if out.returncode != 0:
        return {}

    usage: dict[int, int] = {}
    for line in out.stdout.strip().splitlines():
        parts = [part.strip() for part in line.split(",")]
        if len(parts) != 2:
            continue
        try:
            usage[int(parts[0])] = int(parts[1])
        except ValueError:
            continue
    return usage


def _filter_externally_busy_gpus(
    candidate_gpus: list[int],
    running_jobs: list[Job],
    busy_memory_threshold_mb: int = 4096,
) -> list[int]:
    """Drop free GPUs that already have substantial external memory usage."""
    if not candidate_gpus:
        return []

    scheduler_owned = set()
    for j in running_jobs:
        if j.state == "running" and j.gpus and j.pid and _job_alive(j.pid):
            scheduler_owned.update(int(g) for g in j.gpus.split(","))

    memory_used = _query_gpu_memory_used()
    filtered: list[int] = []
    for gpu in candidate_gpus:
        if gpu in scheduler_owned:
            filtered.append(gpu)
            continue
        if memory_used.get(gpu, 0) >= busy_memory_threshold_mb:
            continue
        filtered.append(gpu)
    return filtered


def _load_task_config(task_name: str) -> dict:
    config_path = PROJECT_ROOT / "tasks" / task_name / "config.json"
    if not config_path.exists():
        raise FileNotFoundError(f"Task config not found: {config_path}")
    return json.loads(config_path.read_text())


def _load_run_config(config_path: str | None) -> dict:
    """Load a scheduler/runtime config file."""
    if not config_path:
        return {}
    path = Path(config_path)
    if not path.is_absolute():
        path = PROJECT_ROOT / path
    if not path.exists():
        return {}
    return yaml.safe_load(path.read_text()) or {}


@lru_cache(maxsize=None)
def _load_package_config(package_name: str) -> dict:
    config_path = PROJECT_ROOT / "vendor" / "pkg_configs" / package_name / "config.json"
    if not config_path.exists():
        return {}
    return json.loads(config_path.read_text())


def _test_cmd_uses_gpu(entry: dict, task_config: dict | None = None) -> bool:
    """Return whether a test command should consume GPU capacity.

    Resolution order is task config first, then package config, then a
    conservative fallback of assuming the job needs a GPU.
    """
    for key in ("use_cuda", "requires_gpu"):
        if key in entry:
            return bool(entry[key])

    task_config = task_config or {}
    for key in ("use_cuda", "requires_gpu"):
        if key in task_config:
            return bool(task_config[key])

    package_name = entry.get("package")
    if package_name:
        package_config = _load_package_config(package_name)
        for key in ("use_cuda", "requires_gpu"):
            if key in package_config:
                return bool(package_config[key])

    return True


_DEFAULT_CPU_ONLY_CONCURRENCY = 4


def _resolve_cpu_only_concurrency(config_path: str | None, cli_value: int | None) -> int:
    """Return the max number of concurrent CPU-only jobs.

    Resolution order: CLI flag → config file → sensible default.
    Never returns None — unlimited CPU-only concurrency is too dangerous
    on shared machines.
    """
    if cli_value is not None:
        return max(1, cli_value)

    run_config = _load_run_config(config_path)
    value = run_config.get("cpu_only_concurrency")
    if value is not None:
        try:
            return max(1, int(value))
        except (TypeError, ValueError):
            pass

    return _DEFAULT_CPU_ONLY_CONCURRENCY


def _job_uses_gpu(job: Job) -> bool:
    """Return whether a queued/running job should count against GPU capacity."""
    return bool(job.gpus) or max(job.gpus_needed, job.min_gpus_needed) > 0


def _filter_test_cmds(
    test_cmds: list[dict],
    groups: list[int] | None = None,
    labels: list[str] | None = None,
) -> list[dict]:
    filtered = list(test_cmds)
    if groups:
        allowed_groups = set(groups)
        filtered = [entry for entry in filtered if entry.get("group") in allowed_groups]
    if labels:
        allowed_labels = set(labels)
        filtered = [entry for entry in filtered if entry.get("label") in allowed_labels]
    return filtered


def infer_gpus_needed(
    task_name: str,
    groups: list[int] | None = None,
    labels: list[str] | None = None,
) -> int:
    """Infer the peak concurrent GPU count for a task after group/label filters."""
    task_config = _load_task_config(task_name)
    test_cmds = _filter_test_cmds(task_config.get("test_cmds", []), groups=groups, labels=labels)
    if not test_cmds:
        return 1
    if not any(_test_cmd_uses_gpu(entry, task_config) for entry in test_cmds):
        return 0

    grouped: dict[int, list[dict]] = {}
    auto_group = 10000
    for entry in test_cmds:
        group = entry.get("group")
        if group is None:
            group = auto_group
            auto_group += 1
        grouped.setdefault(group, []).append(entry)

    peak_gpus = 0
    for entries in grouped.values():
        whole_gpu_jobs = 0
        fractional = 0.0
        for entry in entries:
            if not _test_cmd_uses_gpu(entry, task_config):
                continue
            compute = float(entry.get("compute", 1) or 1)
            if compute >= 1.0:
                whole_gpu_jobs += max(1, math.ceil(compute))
            else:
                fractional += compute
        peak_gpus = max(peak_gpus, whole_gpu_jobs + max(0, math.ceil(fractional)))

    return max(1, peak_gpus)


def infer_min_gpus_needed(
    task_name: str,
    groups: list[int] | None = None,
    labels: list[str] | None = None,
) -> int:
    """Infer the minimum GPU count required to make progress on a task.

    This is lower than ``infer_gpus_needed`` when the peak demand comes from
    parallel commands in the same group rather than a single multi-GPU command.
    """
    task_config = _load_task_config(task_name)
    test_cmds = _filter_test_cmds(task_config.get("test_cmds", []), groups=groups, labels=labels)
    if not test_cmds:
        return 1
    if not any(_test_cmd_uses_gpu(entry, task_config) for entry in test_cmds):
        return 0

    min_gpus = 0
    for entry in test_cmds:
        if not _test_cmd_uses_gpu(entry, task_config):
            continue
        compute = float(entry.get("compute", 1) or 1)
        min_gpus = max(min_gpus, max(1, math.ceil(compute)))
    return max(1, min_gpus)


def _build_extra_args(
    args,
    subcmd: str,
    *,
    include_seed: bool = True,
    include_labels: bool = True,
) -> list[str]:
    extra_args: list[str] = []
    if subcmd == "agent":
        extra_args.extend(["--model", args.model])
    elif subcmd == "baseline":
        if args.name:
            extra_args.extend(["--name", args.name])

    if include_seed and getattr(args, "seed", None) is not None:
        extra_args.extend(["--seed", str(args.seed)])
    for group in getattr(args, "group", []) or []:
        extra_args.extend(["--group", str(group)])
    for label in (getattr(args, "label", []) or []) if include_labels else []:
        extra_args.extend(["--label", label])
    return extra_args


def _can_expand_baseline_jobs(test_cmds: list[dict]) -> bool:
    """Return whether a baseline can be split into single-GPU jobs safely."""
    if not test_cmds:
        return False
    return all(float(entry.get("compute", 1) or 1) <= 1.0 for entry in test_cmds)


def _baseline_names(task_config: dict, requested_name: str | None) -> list[str | None]:
    """Return the baseline names that should become scheduler jobs."""
    if requested_name:
        return [requested_name]
    baselines = task_config.get("baselines", {}) or {}
    if baselines:
        return list(baselines.keys())
    return [None]


def _build_job_specs(args) -> list[dict]:
    """Expand one scheduler add request into one or more concrete jobs."""
    if args.subcmd != "baseline":
        extra_args = _build_extra_args(args, args.subcmd)
        gpus_needed = args.gpus_needed
        if gpus_needed is None:
            gpus_needed = infer_gpus_needed(args.task, groups=args.group, labels=args.label)
        min_gpus_needed = infer_min_gpus_needed(args.task, groups=args.group, labels=args.label)
        return [{
            "task": args.task,
            "args": extra_args,
            "gpus_needed": gpus_needed,
            "min_gpus_needed": min_gpus_needed,
        }]

    task_config = _load_task_config(args.task)
    filtered_cmds = _filter_test_cmds(task_config.get("test_cmds", []), groups=args.group, labels=args.label)
    baselines = task_config.get("baselines", {}) or {}
    should_expand = _can_expand_baseline_jobs(filtered_cmds) and (
        args.task.startswith("pde-") or bool(baselines)
    )
    if not should_expand:
        extra_args = _build_extra_args(args, args.subcmd)
        gpus_needed = args.gpus_needed
        if gpus_needed is None:
            gpus_needed = infer_gpus_needed(args.task, groups=args.group, labels=args.label)
        min_gpus_needed = infer_min_gpus_needed(args.task, groups=args.group, labels=args.label)
        return [{
            "task": args.task,
            "args": extra_args,
            "gpus_needed": gpus_needed,
            "min_gpus_needed": min_gpus_needed,
        }]

    run_config = _load_run_config(args.config)
    task_seeds = task_config.get("seeds")
    if getattr(args, "seed", None) is not None:
        seeds = [args.seed]
    elif task_seeds:
        seeds = task_seeds
    else:
        seeds = run_config.get("seeds", [42])
    labels = [entry["label"] for entry in filtered_cmds if entry.get("label")]
    if not labels:
        labels = [None]
    baseline_names = _baseline_names(task_config, getattr(args, "name", None))
    specs: list[dict] = []
    # Iterate label-first so the queue's first wave spans as many distinct
    # baseline/seed groups as possible. This avoids front-loading multiple
    # jobs that all wait on the same shared training checkpoint.
    for label in labels:
        for seed in seeds:
            for baseline_name in baseline_names:
                extra_args = _build_extra_args(
                    args,
                    args.subcmd,
                    include_seed=False,
                    include_labels=False,
                )
                if baseline_name and "--name" not in extra_args:
                    extra_args.extend(["--name", baseline_name])
                if "--seed" not in extra_args:
                    extra_args.extend(["--seed", str(seed)])
                if label and "--label" not in extra_args:
                    extra_args.extend(["--label", label])
                label_filter = [label] if label else None
                gpus_needed = args.gpus_needed
                if gpus_needed is None:
                    gpus_needed = infer_gpus_needed(args.task, groups=args.group, labels=label_filter)
                min_gpus_needed = infer_min_gpus_needed(args.task, groups=args.group, labels=label_filter)
                specs.append({
                    "task": args.task,
                    "args": extra_args,
                    "gpus_needed": gpus_needed,
                    "min_gpus_needed": min_gpus_needed,
                })
    return specs


# ---------------------------------------------------------------------------
# Commands
# ---------------------------------------------------------------------------

def cmd_add(args):
    """Add an agent or baseline job to the queue."""
    _ensure_dirs()
    job_specs = _build_job_specs(args)
    with _queue_transaction() as jobs:
        created: list[Job] = []
        for spec in job_specs:
            job = Job(
                job_id=_next_id(jobs),
                command=args.subcmd,
                task=spec["task"],
                args=spec["args"],
                config=args.config,
                gpus_needed=spec["gpus_needed"],
                min_gpus_needed=spec["min_gpus_needed"],
            )
            jobs.append(job)
            created.append(job)
    for job in created:
        print(
            f"Added job #{job.job_id}: {job.command} {job.task} {' '.join(job.args)} "
            f"[gpus={job.min_gpus_needed}-{job.gpus_needed}]"
        )


def cmd_batch(args):
    """Batch-add all tasks matching a domain prefix."""
    _ensure_dirs()
    tasks_dir = PROJECT_ROOT / "tasks"

    matching = []
    for d in sorted(tasks_dir.iterdir()):
        if not d.is_dir():
            continue
        if not (d / "config.json").exists():
            continue
        if args.domain == "all" or d.name.startswith(args.domain + "-") or d.name == args.domain:
            if args.exclude and d.name in args.exclude.split(","):
                continue
            matching.append(d.name)

    if not matching:
        print(f"No tasks found for domain '{args.domain}'")
        return

    created_count = 0
    with _queue_transaction() as jobs:
        for task in matching:
            task_args = argparse.Namespace(**vars(args))
            task_args.task = task
            job_specs = _build_job_specs(task_args)
            for spec in job_specs:
                job = Job(
                    job_id=_next_id(jobs),
                    command=args.subcmd,
                    task=task,
                    args=spec["args"],
                    config=args.config,
                    gpus_needed=spec["gpus_needed"],
                    min_gpus_needed=spec["min_gpus_needed"],
                )
                jobs.append(job)
                created_count += 1
                print(
                    f"  Added job #{job.job_id}: {job.command} {task} "
                    f"{' '.join(job.args)} [gpus={job.min_gpus_needed}-{job.gpus_needed}]"
                )

    print(f"\nAdded {created_count} jobs. Run 'python -m mlsbench.scheduler start' to begin.")


def cmd_list(args):
    """List all jobs in the queue."""
    jobs = _load_queue()
    if not jobs:
        print("Queue is empty.")
        return

    print(f"{'ID':>4}  {'State':<10}  {'GPUs':<6}  {'Command':<10}  {'Task':<40}  {'Extra'}")
    print("-" * 100)
    for j in jobs:
        extra = " ".join(j.args)
        if j.gpus:
            gpus = j.gpus
        elif max(j.gpus_needed, j.min_gpus_needed) == 0:
            gpus = "CPU"
        else:
            gpus = f"need:{j.min_gpus_needed}-{j.gpus_needed}"
        print(f"{j.job_id:>4}  {j.state:<10}  {gpus:<6}  {j.command:<10}  {j.task:<40}  {extra}")


def cmd_status(args):
    """Show scheduler status and running jobs."""
    pid = _read_scheduler_pid()
    if pid is not None:
        if _scheduler_pid_is_valid(pid):
            print(f"Scheduler running (PID {pid})")
        else:
            print("Scheduler not running (stale PID file)")
    else:
        print("Scheduler not running")

    jobs = _load_queue()
    running = [j for j in jobs if j.state == "running" and j.pid and _job_alive(j.pid)]
    stale = [j for j in jobs if j.state == "running" and (not j.pid or not _job_alive(j.pid))]
    queued = [j for j in jobs if j.state == "queued"]
    completed = [j for j in jobs if j.state == "completed"]
    failed = [j for j in jobs if j.state == "failed"]

    print(f"\nQueued: {len(queued)}  Running: {len(running)}  "
          f"Completed: {len(completed)}  Failed: {len(failed)}  Stale: {len(stale)}")

    if running:
        print("\nRunning:")
        for j in running:
            gpu_label = f"GPU {j.gpus}" if j.gpus else "CPU-only"
            print(f"  #{j.job_id} {j.command} {j.task} [{gpu_label}] "
                  f"PID={j.pid} started={j.started_at}")
    if stale:
        print("\nStale:")
        for j in stale:
            print(f"  #{j.job_id} {j.command} {j.task} [last GPU {j.gpus or '-'}] "
                  f"dead_pid={j.pid or '-'}")
    if queued:
        print("\nNext in queue:")
        for j in queued[:5]:
            if max(j.gpus_needed, j.min_gpus_needed) == 0:
                res_label = "CPU-only"
            else:
                res_label = f"needs {j.min_gpus_needed}-{j.gpus_needed} GPU"
            print(f"  #{j.job_id} {j.command} {j.task} ({res_label})")


def cmd_cancel(args):
    """Cancel a job (kill if running, including all descendant processes)."""
    with _queue_transaction() as jobs:
        for j in jobs:
            if j.job_id == args.job_id:
                if j.state == "running" and j.pid:
                    print(f"Killing job #{j.job_id} process tree from PID {j.pid} ...")
                    _kill_job_processes(j, timeout=5.0)
                    print(f"Job #{j.job_id} processes terminated.")
                j.state = "cancelled"
                j.finished_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                print(f"Job #{j.job_id} cancelled.")
                return
    print(f"Job #{args.job_id} not found.")


def cmd_clear(args):
    """Remove completed/failed/cancelled jobs from the queue."""
    with _queue_transaction() as jobs:
        kept = [j for j in jobs if j.state in ("queued", "running")]
        removed = len(jobs) - len(kept)
        jobs[:] = kept
    print(f"Cleared {removed} finished jobs, {len(kept)} remaining.")


def cmd_start(args):
    """Start the scheduler loop."""
    _ensure_dirs()

    existing_pid = _read_scheduler_pid()
    if existing_pid is not None and existing_pid != os.getpid() and _scheduler_pid_is_valid(existing_pid):
        print(f"Scheduler already running (PID {existing_pid})", file=sys.stderr)
        sys.exit(1)

    # Parse GPU list
    if args.gpus:
        all_gpus = [int(g) for g in args.gpus.split(",")]
    else:
        n = _get_available_gpu_count()
        all_gpus = list(range(n))

    if not all_gpus:
        print("ERROR: No GPUs detected. Use --gpus to specify manually.", file=sys.stderr)
        sys.exit(1)

    print(f"Scheduler starting with GPUs: {all_gpus}")

    # Resolve CPU-only concurrency: CLI flag → scheduler --config → first job's config → default
    _start_config = args.config
    if not _start_config:
        with _queue_transaction() as _q:
            for _j in _q:
                if _j.config:
                    _start_config = _j.config
                    break
    cpu_only_limit = _resolve_cpu_only_concurrency(_start_config, getattr(args, "max_cpu_only", None))
    print(f"CPU-only concurrency limit: {cpu_only_limit}")

    # Write PID
    PID_FILE.write_text(str(os.getpid()))

    # Handle signals
    stop = False
    def _handle_signal(sig, frame):
        nonlocal stop
        print(f"\nReceived signal {sig}, stopping after current jobs finish...")
        stop = True
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    processes: dict[int, subprocess.Popen] = {}  # job_id -> Popen

    with _queue_transaction() as jobs:
        requeued = _requeue_stale_running_jobs(jobs)
        for job_id in requeued:
            print(f"Recovered stale job #{job_id}: requeued")

    try:
        while not stop:
            with _queue_transaction() as jobs:
                requeued = _requeue_stale_running_jobs(jobs, tracked_job_ids=set(processes))
                for job_id in requeued:
                    print(f"Recovered stale job #{job_id}: requeued")

                # Check running jobs for completion or timeout
                for j in jobs:
                    if j.state == "running" and j.job_id in processes:
                        proc = processes[j.job_id]
                        ret = proc.poll()
                        if ret is not None:
                            # Main process exited — kill any orphaned descendants
                            # that may still be holding GPUs.
                            _kill_job_processes(j, proc.pid, timeout=5.0)
                            j.exit_code = ret
                            j.state = "completed" if ret == 0 else "failed"
                            j.finished_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                            del processes[j.job_id]
                            status = "completed" if ret == 0 else f"failed (exit={ret})"
                            print(f"[{j.finished_at}] Job #{j.job_id} {j.task} {status}")
                        elif j.timeout_secs > 0 and j.started_at:
                            # Enforce wall-time limit
                            started = datetime.strptime(j.started_at, "%Y-%m-%d %H:%M:%S")
                            elapsed = (datetime.now() - started).total_seconds()
                            if elapsed > j.timeout_secs:
                                print(f"[{datetime.now():%Y-%m-%d %H:%M:%S}] Job #{j.job_id} "
                                      f"TIMEOUT after {elapsed:.0f}s (limit {j.timeout_secs}s)")
                                _kill_job_processes(j, proc.pid, timeout=5.0)
                                j.exit_code = -9
                                j.state = "failed"
                                j.finished_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                                del processes[j.job_id]

                # Find free GPUs
                free_gpus = _get_free_gpus(all_gpus, jobs)
                if not getattr(args, "ignore_busy", False):
                    free_gpus = _filter_externally_busy_gpus(free_gpus, jobs)
                running_cpu_only = sum(
                    1
                    for j in jobs
                    if j.state == "running" and j.pid and _job_alive(j.pid) and not _job_uses_gpu(j)
                )

                # Launch queued jobs if GPUs available
                for j in jobs:
                    if j.state != "queued":
                        continue
                    if _job_uses_gpu(j):
                        if j.min_gpus_needed > len(free_gpus):
                            continue
                        # Assign GPUs
                        assign_count = min(j.gpus_needed, len(free_gpus))
                        assigned = free_gpus[:assign_count]
                        free_gpus = free_gpus[assign_count:]
                        j.gpus = ",".join(str(g) for g in assigned)
                    else:
                        if running_cpu_only >= cpu_only_limit:
                            continue
                        j.gpus = ""
                        running_cpu_only += 1

                    # Build command
                    config = args.config or j.config
                    if j.command == "script":
                        # Raw script execution: task field holds the script path
                        cmd = ["bash", j.task]
                    else:
                        cmd = [
                            sys.executable, "-m", "mlsbench",
                            j.command, j.task,
                            "--config", config,
                        ] + j.args

                    # Log file
                    task_slug = Path(j.task).stem if j.command == "script" else j.task
                    log_name = f"job{j.job_id}_{j.command}_{task_slug}_{datetime.now():%Y%m%d_%H%M%S}.log"
                    log_path = LOG_DIR / log_name
                    j.log_file = str(log_path)

                    # Set CUDA_VISIBLE_DEVICES
                    env = os.environ.copy()
                    env["MLSBENCH_SCHEDULER_MANAGED"] = "1"
                    env["CUDA_VISIBLE_DEVICES"] = j.gpus
                    env["NVIDIA_VISIBLE_DEVICES"] = j.gpus
                    src_path = str(PROJECT_ROOT / "src")
                    existing_pythonpath = env.get("PYTHONPATH", "")
                    env["PYTHONPATH"] = (
                        src_path if not existing_pythonpath
                        else f"{src_path}{os.pathsep}{existing_pythonpath}"
                    )

                    # Launch — each job gets its own session so we can
                    # track and kill the entire process tree via PGID.
                    log_fh = open(log_path, "w")
                    proc = subprocess.Popen(
                        cmd, stdout=log_fh, stderr=subprocess.STDOUT,
                        env=env, cwd=str(PROJECT_ROOT),
                        start_new_session=True,
                    )
                    log_fh.close()
                    processes[j.job_id] = proc
                    j.pid = proc.pid
                    j.state = "running"
                    j.started_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    gpu_label = f"GPU {j.gpus}" if j.gpus else "CPU-only"
                    print(f"[{j.started_at}] Started job #{j.job_id}: {j.command} {j.task} "
                          f"[{gpu_label}] PID={j.pid}")

            # If nothing queued and nothing running, exit (unless --daemon)
            if not getattr(args, "daemon", False):
                if not any(j.state in ("queued", "running") for j in jobs):
                    print("All jobs finished.")
                    break

            time.sleep(5)

    finally:
        current_pid = _read_scheduler_pid()
        if current_pid == os.getpid():
            PID_FILE.unlink(missing_ok=True)
        # Kill any still-running process *groups* on exit
        for job_id, proc in processes.items():
            if proc.poll() is None or _process_group_alive(proc.pid):
                print(f"Terminating job #{job_id} (process tree from PID {proc.pid})")
                cleanup_job = next((j for j in _load_queue() if j.job_id == job_id), None)
                if cleanup_job is not None:
                    _kill_job_processes(cleanup_job, proc.pid, timeout=5.0)
                else:
                    _kill_process_group(proc.pid, timeout=5.0)
                    _kill_process_tree(proc.pid, timeout=5.0)


# ---------------------------------------------------------------------------
# Programmatic API for submitting script jobs (used by LocalSchedulerExecutor)
# ---------------------------------------------------------------------------


def submit_script_job(
    script_path: str,
    gpus_needed: int = 1,
    job_name: str = "",
    timeout_secs: int = 0,
) -> int:
    """Add a 'script' job to the queue. Returns the job_id.

    Args:
        timeout_secs: Wall-time limit in seconds. 0 = no limit.
    """
    _ensure_dirs()
    with _queue_transaction() as jobs:
        job = Job(
            job_id=_next_id(jobs),
            command="script",
            task=script_path,
            args=[],
            config="",
            gpus_needed=gpus_needed,
            min_gpus_needed=gpus_needed,
            timeout_secs=timeout_secs,
        )
        jobs.append(job)
    return job.job_id


def poll_job(job_id: int) -> tuple[str, int, str]:
    """Check a job's current state. Returns (state, exit_code, log_file)."""
    jobs = _load_queue()
    for j in jobs:
        if j.job_id == job_id:
            return j.state, j.exit_code, j.log_file
    return "unknown", -1, ""


def wait_for_job(job_id: int, poll_interval: float = 3.0, timeout: float = 7200) -> str:
    """Block until a job reaches a terminal state. Returns the final state."""
    terminal = {"completed", "failed", "cancelled"}
    start = time.time()
    while True:
        state, _, _ = poll_job(job_id)
        if state in terminal:
            return state
        if time.time() - start > timeout:
            return "timeout"
        time.sleep(poll_interval)


def is_scheduler_running() -> bool:
    """Check if the scheduler daemon is alive."""
    pid = _read_scheduler_pid()
    return pid is not None and _scheduler_pid_is_valid(pid)


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main():
    parser = argparse.ArgumentParser(
        description="Lightweight GPU-aware task scheduler for MLS-Bench",
    )
    sub = parser.add_subparsers(dest="action", required=True)

    # add
    p_add = sub.add_parser("add", help="Add a single job")
    p_add.add_argument("subcmd", choices=["agent", "baseline"], help="mlsbench subcommand")
    p_add.add_argument("task", help="Task name")
    p_add.add_argument("--model", default="claude-sonnet-4-6")
    p_add.add_argument("--name", default=None, help="Baseline name")
    p_add.add_argument("--seed", type=int, default=None, help="Optional seed override passed through to mlsbench")
    p_add.add_argument("--group", type=int, action="append", default=None, help="Optional test group filter")
    p_add.add_argument("--label", action="append", default=None, help="Optional test label filter")
    p_add.add_argument("--config", default="configs/config.yaml")
    p_add.add_argument("--gpus-needed", type=int, default=None, help="GPUs per job (default: infer from task config)")
    p_add.set_defaults(func=cmd_add)

    # batch
    p_batch = sub.add_parser("batch", help="Batch-add tasks by domain")
    p_batch.add_argument("subcmd", choices=["agent", "baseline"])
    p_batch.add_argument("domain", help="Domain prefix or 'all'")
    p_batch.add_argument("--model", default="claude-sonnet-4-6")
    p_batch.add_argument("--name", default=None, help="Baseline name (for baseline)")
    p_batch.add_argument("--seed", type=int, default=None, help="Optional seed override passed through to mlsbench")
    p_batch.add_argument("--group", type=int, action="append", default=None, help="Optional test group filter")
    p_batch.add_argument("--label", action="append", default=None, help="Optional test label filter")
    p_batch.add_argument("--config", default="configs/config.yaml")
    p_batch.add_argument("--gpus-needed", type=int, default=None)
    p_batch.add_argument("--exclude", default="", help="Comma-separated tasks to exclude")
    p_batch.set_defaults(func=cmd_batch)

    # list
    p_list = sub.add_parser("list", help="List all jobs")
    p_list.set_defaults(func=cmd_list)

    # status
    p_status = sub.add_parser("status", help="Show scheduler status")
    p_status.set_defaults(func=cmd_status)

    # start
    p_start = sub.add_parser("start", help="Start the scheduler")
    p_start.add_argument("--gpus", default="", help="Comma-separated GPU indices (default: auto-detect)")
    p_start.add_argument("--config", default=None, help="Override config for all jobs")
    p_start.add_argument("--ignore-busy", action="store_true",
                         help="Skip external GPU memory check (use when sharing GPUs with other workloads)")
    p_start.add_argument("--max-cpu-only", type=int, default=None,
                         help="Max concurrent CPU-only jobs (default: read cpu_only_concurrency from config)")
    p_start.add_argument("--daemon", action="store_true",
                         help="Keep running even when queue is empty (for dynamic job submission from agents)")
    p_start.set_defaults(func=cmd_start)

    # cancel
    p_cancel = sub.add_parser("cancel", help="Cancel a job")
    p_cancel.add_argument("job_id", type=int)
    p_cancel.set_defaults(func=cmd_cancel)

    # clear
    p_clear = sub.add_parser("clear", help="Remove finished jobs from queue")
    p_clear.set_defaults(func=cmd_clear)

    args = parser.parse_args()
    args.func(args)


if __name__ == "__main__":
    main()

"""MLS-Bench score normalization system.

Provides unified [0,1] scoring across tasks with different metrics.
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path


def register_score_subcommand(subparsers: argparse._SubParsersAction) -> None:
    """Register the ``score`` subcommand with the main CLI parser."""
    p_score = subparsers.add_parser(
        "score",
        help="Compute normalized scores from leaderboard results",
    )

    p_score.add_argument(
        "task", nargs="?", default=None,
        help="Task name to score. Omit with --all to score everything.",
    )
    p_score.add_argument(
        "--all", action="store_true", dest="score_all",
        help="Score all tasks that have a score_spec.py",
    )
    p_score.add_argument(
        "--model", default=None,
        help="Only score a specific model (default: all models in leaderboard)",
    )
    p_score.add_argument(
        "--format", choices=["table", "json", "csv"], default="table",
        dest="out_format",
        help="Output format (default: table)",
    )
    p_score.add_argument(
        "--summary", action="store_true",
        help="Only show task-level scores (with --all)",
    )
    p_score.add_argument(
        "-v", "--verbose", action="store_true",
        help="Show per-term details",
    )
    p_score.add_argument(
        "--check", action="store_true",
        help="Validate score_spec files without scoring",
    )
    p_score.add_argument(
        "--anchors", action="store_true",
        help="Show baseline anchors for a task",
    )
    p_score.add_argument(
        "--autogen", action="store_true",
        help="Auto-generate score_spec.py templates from leaderboard data",
    )
    p_score.add_argument(
        "--force", action="store_true",
        help="Overwrite existing score_spec.py (with --autogen)",
    )
    p_score.add_argument(
        "--dry-run", action="store_true",
        help="Print generated spec without writing (with --autogen)",
    )

    p_score.set_defaults(func=cmd_score)


def cmd_score(args: argparse.Namespace) -> None:
    """Handler for the ``mlsbench score`` subcommand."""
    from mlsbench import PROJECT_ROOT
    tasks_dir = PROJECT_ROOT / "tasks"

    if args.autogen:
        _cmd_autogen(args, tasks_dir)
        return

    if args.anchors:
        _cmd_anchors(args, tasks_dir)
        return

    if args.check:
        _cmd_check(args, tasks_dir)
        return

    if args.score_all:
        _cmd_score_all(args, tasks_dir)
    elif args.task:
        _cmd_score_task(args, tasks_dir)
    else:
        print("Error: specify a task name or use --all", file=sys.stderr)
        sys.exit(1)


def _cmd_score_task(args: argparse.Namespace, tasks_dir: Path) -> None:
    from mlsbench.scoring.evaluate import evaluate_task
    from mlsbench.scoring.report import format_task_detail

    results = evaluate_task(args.task, model=args.model, tasks_dir=tasks_dir)
    if not results:
        print(f"No results for task '{args.task}'. Check score_spec.py and leaderboard.csv exist.")
        return

    if args.out_format == "json":
        from mlsbench.scoring.report import results_to_json
        print(results_to_json({args.task: results}))
    elif args.out_format == "csv":
        from mlsbench.scoring.report import results_to_csv
        print(results_to_csv({args.task: results}))
    else:
        print(format_task_detail(results, verbose=args.verbose))


def _cmd_score_all(args: argparse.Namespace, tasks_dir: Path) -> None:
    from mlsbench.scoring.evaluate import evaluate_all
    from mlsbench.scoring.report import format_summary_table, format_task_detail

    models = [args.model] if args.model else None
    all_results = evaluate_all(tasks_dir=tasks_dir, models=models)

    if not all_results:
        print("No scored tasks found. Ensure tasks have score_spec.py files.")
        return

    if args.out_format == "json":
        from mlsbench.scoring.report import results_to_json
        print(results_to_json(all_results))
    elif args.out_format == "csv":
        from mlsbench.scoring.report import results_to_csv
        print(results_to_csv(all_results))
    else:
        if args.summary:
            print(format_summary_table(all_results, summary_only=True))
        else:
            # Print summary table first
            print(format_summary_table(all_results))
            print()
            # Then per-task details if verbose
            if args.verbose:
                for task_name in sorted(all_results.keys()):
                    print(format_task_detail(all_results[task_name], verbose=True))
                    print()


def _cmd_check(args: argparse.Namespace, tasks_dir: Path) -> None:
    from mlsbench.scoring.anchors import BaselineAnchors
    from mlsbench.scoring.evaluate import load_expanded_spec
    from mlsbench.scoring.spec import leaderboard_declared_metrics, validate_score_spec

    targets: list[Path] = []
    if args.task:
        targets.append(tasks_dir / args.task)
    else:
        for d in sorted(tasks_dir.iterdir()):
            if d.is_dir() and (d / "score_spec.py").exists():
                targets.append(d)

    if not targets:
        print("No score_spec.py files found.")
        return

    total_warns = 0
    for task_dir in targets:
        task_name = task_dir.name
        anchors = BaselineAnchors(task_dir)
        spec = load_expanded_spec(task_dir, anchors)
        if spec is None:
            print(f"  {task_name}: no score_spec.py")
            continue

        if (task_dir / "leaderboard.csv").exists():
            available_metrics = sorted(set(anchors.metric_columns()) | set(leaderboard_declared_metrics(task_dir)))
        else:
            available_metrics = [ts.metric for ts in spec.terms.values()]
        warns = validate_score_spec(spec, available_metrics)
        if not (task_dir / "leaderboard.csv").exists():
            warns.append("leaderboard.csv not found; baseline anchors unavailable")
        else:
            missing_anchor_metrics: list[str] = []
            for tspec in spec.terms.values():
                if tspec.role == "drop":
                    continue
                if tspec.metric not in available_metrics:
                    continue
                if anchors.worst_for(tspec.metric, tspec.direction) is None:
                    missing_anchor_metrics.append(tspec.metric)
            if missing_anchor_metrics:
                metrics = sorted(set(missing_anchor_metrics))
                preview = ", ".join(metrics[:8])
                if len(metrics) > 8:
                    preview += f", ... (+{len(metrics) - 8} more)"
                warns.append(
                    f"{len(metrics)} metric(s) have no current baseline anchor: {preview}"
                )

        status = "OK" if not warns else f"{len(warns)} warning(s)"
        print(f"  {task_name}: {len(spec.terms)} terms, {len(spec.settings)} settings — {status}")
        for w in warns:
            print(f"    WARNING: {w}")
            total_warns += 1

    print(f"\nChecked {len(targets)} task(s), {total_warns} warning(s) total.")


def _cmd_anchors(args: argparse.Namespace, tasks_dir: Path) -> None:
    from mlsbench.scoring.anchors import BaselineAnchors
    from mlsbench.scoring.evaluate import load_expanded_spec

    if not args.task:
        print("Error: --anchors requires a task name", file=sys.stderr)
        sys.exit(1)

    task_dir = tasks_dir / args.task
    anchors = BaselineAnchors(task_dir)
    spec = load_expanded_spec(task_dir, anchors)
    directions: dict[str, str] = {}
    if spec:
        for term in spec.terms.values():
            previous = directions.get(term.metric)
            if previous is None:
                directions[term.metric] = term.direction
            elif previous != term.direction:
                directions[term.metric] = "mixed"

    bl_names = anchors.baseline_names()
    if not bl_names:
        print(f"No baselines found for task '{args.task}'.")
        return

    print(f"Task: {args.task}")
    print(f"Baselines: {', '.join(bl_names)}")
    print()

    if spec and spec.terms:
        cols = []
        seen = set()
        for term in spec.terms.values():
            if term.metric not in seen:
                cols.append(term.metric)
                seen.add(term.metric)
    else:
        cols = anchors.metric_columns()
    if not cols:
        print("No metric columns found.")
        return

    max_col = max(len(c) for c in cols)
    print(f"  {'Metric':<{max_col}}  {'Direction':>9}  {'Worst':>12}  {'Best':>12}")
    print(f"  {'-' * max_col}  {'-' * 9}  {'-' * 12}  {'-' * 12}")
    for c in cols:
        a = anchors.get(c)
        if a:
            direction = directions.get(c, "raw")
            if direction in {"higher", "lower"}:
                worst = anchors.worst_for(c, direction)
                best = anchors.best_for(c, direction)
            else:
                worst = a.worst
                best = a.best
            print(f"  {c:<{max_col}}  {direction:>9}  {worst:>12.4f}  {best:>12.4f}")
        else:
            direction = directions.get(c, "raw")
            print(f"  {c:<{max_col}}  {direction:>9}  {'missing':>12}  {'missing':>12}")


def _cmd_autogen(args: argparse.Namespace, tasks_dir: Path) -> None:
    from mlsbench.scoring.autogen import autogen_score_spec

    targets: list[str] = []
    if args.task:
        targets.append(args.task)
    else:
        # All tasks with leaderboard but no score_spec (unless --force)
        for d in sorted(tasks_dir.iterdir()):
            if not d.is_dir():
                continue
            if not (d / "leaderboard.csv").exists():
                continue
            if (d / "score_spec.py").exists() and not args.force:
                continue
            targets.append(d.name)

    if not targets:
        print("No tasks to generate score_spec for.")
        return

    generated = 0
    skipped = 0
    for task_name in targets:
        task_dir = tasks_dir / task_name
        if (task_dir / "score_spec.py").exists() and not args.force:
            skipped += 1
            continue

        source = autogen_score_spec(task_name, tasks_dir=tasks_dir, dry_run=args.dry_run)

        if args.dry_run:
            print(f"=== {task_name} ===")
            print(source)
            print()
        else:
            print(f"  {task_name}: generated")
        generated += 1

    action = "would generate" if args.dry_run else "generated"
    print(f"\n{action} {generated} score_spec(s), skipped {skipped} existing.")

"""Extract baseline anchors from leaderboard CSV.

Reads ``tasks/<task>/leaderboard.csv`` and identifies baseline rows
(``model=baseline:*``). Provides worst/best per-metric values for use
in normalization primitives.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path

META_COLS = {"timestamp", "model", "is_final", "seed"}
INFORMATIONAL_PREFIXES = ("elapsed_", "n_samples", "n_prompts")


def _is_final(record: dict) -> bool:
    return str(record.get("is_final", "")).lower() == "true"


def _is_real_metric_value(value) -> bool:
    return isinstance(value, (int, float)) and not (
        isinstance(value, float) and value != value
    )


def _metric_count(record: dict) -> int:
    count = 0
    for key, value in record.items():
        if key in META_COLS:
            continue
        if str(key).startswith(INFORMATIONAL_PREFIXES) or str(key).endswith("_std"):
            continue
        if _is_real_metric_value(value):
            count += 1
    return count


def _baseline_row_priority(record: dict) -> tuple[int, bool, bool, str]:
    return (
        _metric_count(record),
        record.get("seed") == "mean",
        _is_final(record),
        str(record.get("timestamp", "")),
    )


@dataclass
class MetricAnchors:
    """Baseline anchor values for a single metric column."""
    worst: float
    best: float
    values: list[float] = field(default_factory=list)


class BaselineAnchors:
    """Read-only access to baseline anchor values from a task leaderboard."""

    def __init__(self, task_dir: Path):
        self._task_dir = Path(task_dir)
        self._anchors: dict[str, MetricAnchors] = {}
        self._baseline_names: list[str] = []
        self._metric_cols: list[str] = []
        self._load()

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def worst(self, metric: str) -> float | None:
        a = self._anchors.get(metric)
        return a.worst if a else None

    def best(self, metric: str) -> float | None:
        a = self._anchors.get(metric)
        return a.best if a else None

    def worst_for(self, metric: str, direction: str) -> float | None:
        """Return the raw baseline value that is worst for *direction*.

        ``worst()`` preserves the historical raw minimum API. Scoring code
        should use this helper so lower-is-better metrics floor at the raw
        maximum instead.
        """
        a = self._anchors.get(metric)
        if not a:
            return None
        if direction == "lower":
            return a.best
        return a.worst

    def best_for(self, metric: str, direction: str) -> float | None:
        """Return the raw baseline value that is best for *direction*."""
        a = self._anchors.get(metric)
        if not a:
            return None
        if direction == "lower":
            return a.worst
        return a.best

    def get(self, metric: str) -> MetricAnchors | None:
        return self._anchors.get(metric)

    def metric_columns(self) -> list[str]:
        """All scorable metric column names (excludes meta, elapsed_, *_std)."""
        return list(self._metric_cols)

    def baseline_names(self) -> list[str]:
        return list(self._baseline_names)

    # ------------------------------------------------------------------
    # Internal
    # ------------------------------------------------------------------

    def _load(self) -> None:
        from mlsbench.agent.leaderboard import Leaderboard

        lb_path = self._task_dir / "leaderboard.csv"
        if not lb_path.exists():
            return

        lb = Leaderboard(lb_path)
        records = lb.all_records()
        if not records:
            return

        cfg_path = self._task_dir / "config.json"
        bl_keys: set[str] = set()
        if cfg_path.exists():
            cfg = json.loads(cfg_path.read_text())
            bl_keys = set(cfg.get("baselines", {}).keys())

        # Identify current baseline rows. When config.json declares the current
        # baseline set, ignore stale baseline rows left over from older task
        # versions. Some valid historical anchors were not marked final, so
        # ``is_final`` is a preference signal rather than a hard filter.
        baseline_groups: dict[str, list[dict]] = {}
        for r in records:
            model = r.get("model")
            if not isinstance(model, str):
                continue
            if model.startswith("baseline:"):
                # str.removeprefix is Python 3.9+; slice instead so the scorer
                # runs under the task images' own 3.8 interpreter (the prefix is
                # guaranteed present by the startswith guard above).
                name = model[len("baseline:"):]
            elif model in bl_keys:
                name = model
            else:
                continue
            if bl_keys and name not in bl_keys:
                continue
            baseline_groups.setdefault(name, []).append(r)

        baseline_rows: list[tuple[str, dict]] = []
        for name, rows_for_baseline in baseline_groups.items():
            rows_with_metrics = [r for r in rows_for_baseline if _metric_count(r) > 0]
            if rows_with_metrics:
                baseline_rows.append((name, max(rows_with_metrics, key=_baseline_row_priority)))

        if not baseline_rows:
            return

        self._baseline_names = [f"baseline:{name}" for name, _ in sorted(baseline_rows)]

        data_rows = [r for _, r in baseline_rows]

        # Discover metric columns. ``metric_columns()`` intentionally excludes
        # elapsed_* so autogen does not score wall time by default, but explicit
        # score_specs may still reference elapsed_*; keep anchors for those.
        anchor_cols: list[str] = []
        seen: set[str] = set()
        for r in records:
            for k in r:
                if k in seen:
                    continue
                seen.add(k)
                if k in META_COLS:
                    continue
                if k.endswith("_std"):
                    continue
                if _is_real_metric_value(r[k]):
                    anchor_cols.append(k)

        # Compute per-metric anchors from baseline data rows
        for col in anchor_cols:
            vals: list[float] = []
            for r in data_rows:
                v = r.get(col)
                if _is_real_metric_value(v):
                    vals.append(float(v))
            if vals:
                self._anchors[col] = MetricAnchors(
                    worst=min(vals),
                    best=max(vals),
                    values=vals,
                )

        self._metric_cols = [
            col for col in anchor_cols
            if col in self._anchors and not col.startswith(INFORMATIONAL_PREFIXES)
        ]

"""Output formatting for score results (terminal tables, JSON, CSV)."""

from __future__ import annotations

import csv
import io
import json
from typing import Any

from mlsbench.scoring.evaluate import SettingResult, TaskResult


# ---------------------------------------------------------------------------
# Terminal table formatting
# ---------------------------------------------------------------------------

def format_task_detail(results: list[TaskResult], verbose: bool = False) -> str:
    """Render detailed scoring results for a single task."""
    if not results:
        return "No results to display."

    parts: list[str] = []
    task_name = results[0].task

    for tr in results:
        lines: list[str] = []
        lines.append(f"Task: {task_name}")
        lines.append(f"Model: {tr.model}")
        lines.append("")

        if tr.settings:
            # Setting table
            max_sname = max(len(sr.name) for sr in tr.settings)
            max_sname = max(max_sname, len("Setting"))
            hdr = f"  {'Setting':<{max_sname}} | Score"
            sep = f"  {'-' * max_sname}-+------"
            lines.append(hdr)
            lines.append(sep)
            for sr in tr.settings:
                lines.append(f"  {sr.name:<{max_sname}} | {sr.score:.3f}")
            lines.append(sep)
            lines.append(f"  {'Task Score (gmean)':<{max_sname}} | {tr.score:.3f}")
        else:
            lines.append(f"  Task Score: {tr.score:.3f}")

        if verbose and tr.settings:
            lines.append("")
            lines.append("  Term Details:")
            for sr in tr.settings:
                for t in sr.terms:
                    p = t.params
                    if t.score == 0.0 and p.get("reason") == "missing_value":
                        detail = "(missing)"
                    elif "gamma" in p:
                        detail = f"(bounded_power, gamma={p['gamma']:.2f})"
                    elif "scale" in p:
                        detail = f"(sigmoid, scale={p['scale']:.1f})"
                    elif "target" in p:
                        detail = f"(penalty, target={p['target']})"
                    else:
                        detail = ""
                    raw_str = f"{t.raw:.4f}" if not (t.raw != t.raw) else "NaN"
                    lines.append(
                        f"    [{sr.name}] {t.metric}: raw={raw_str} -> score={t.score:.3f} {detail}"
                    )

        if tr.warnings:
            lines.append("")
            for w in tr.warnings:
                lines.append(f"  WARNING: {w}")

        parts.append("\n".join(lines))

    return "\n\n".join(parts)


def format_summary_table(
    all_results: dict[str, list[TaskResult]],
    summary_only: bool = False,
) -> str:
    """Render a cross-task summary table.

    Columns: Task | model1 | model2 | ...
    """
    if not all_results:
        return "No scored tasks found."

    # Collect all models
    model_set: set[str] = set()
    for task_results in all_results.values():
        for tr in task_results:
            model_set.add(tr.model)
    models = sorted(model_set)

    if not models:
        return "No agent results found."

    # Build score lookup: {(task, model): score}
    scores: dict[tuple[str, str], float | None] = {}
    for task_name, task_results in all_results.items():
        for tr in task_results:
            scores[(task_name, tr.model)] = tr.score

    tasks = sorted(all_results.keys())

    # Format model names (truncate for display)
    def _short_model(m: str) -> str:
        # Remove common prefixes
        for prefix in ("claude-", "deepseek-", "gpt-", "qwen-"):
            if m.startswith(prefix):
                return m
        return m[:20]

    model_headers = [_short_model(m) for m in models]
    col_width = max(13, max(len(h) for h in model_headers) + 2)
    task_width = max(30, max(len(t) for t in tasks) + 2)

    lines: list[str] = []

    # Header
    hdr = f"{'Task':<{task_width}}"
    for mh in model_headers:
        hdr += f" | {mh:>{col_width}}"
    lines.append(hdr)

    # Separator
    sep = "-" * task_width
    for _ in models:
        sep += "-+-" + "-" * col_width
    lines.append(sep)

    # Rows
    model_task_scores: dict[str, list[float]] = {m: [] for m in models}
    for task_name in tasks:
        row = f"{task_name:<{task_width}}"
        for m in models:
            s = scores.get((task_name, m))
            if s is not None:
                row += f" | {s:>{col_width}.3f}"
                model_task_scores[m].append(s)
            else:
                row += f" | {'—':>{col_width}}"
        lines.append(row)

    # Overall row (gmean across tasks)
    lines.append(sep)
    from mlsbench.scoring.evaluate import _gmean
    overall_row = f"{'Overall (gmean)':<{task_width}}"
    for m in models:
        ts = model_task_scores[m]
        if ts:
            overall = _gmean(ts)
            overall_row += f" | {overall:>{col_width}.3f}"
        else:
            overall_row += f" | {'—':>{col_width}}"
    lines.append(overall_row)

    return "\n".join(lines)


# ---------------------------------------------------------------------------
# JSON / CSV export
# ---------------------------------------------------------------------------

def results_to_json(all_results: dict[str, list[TaskResult]], indent: int = 2) -> str:
    """Serialize all results to JSON."""
    data: dict[str, Any] = {}
    for task_name, task_results in all_results.items():
        data[task_name] = []
        for tr in task_results:
            entry: dict[str, Any] = {
                "model": tr.model,
                "task_score": tr.score,
                "settings": [],
            }
            for sr in tr.settings:
                s_entry: dict[str, Any] = {
                    "name": sr.name,
                    "score": sr.score,
                    "objective_score": sr.objective_score,
                    "penalty": sr.penalty,
                    "terms": [],
                }
                for t in sr.terms:
                    s_entry["terms"].append({
                        "name": t.name,
                        "metric": t.metric,
                        "raw": None if (isinstance(t.raw, float) and t.raw != t.raw) else t.raw,
                        "score": t.score,
                    })
                entry["settings"].append(s_entry)
            if tr.warnings:
                entry["warnings"] = tr.warnings
            data[task_name].append(entry)
    return json.dumps(data, indent=indent, ensure_ascii=False)


def results_to_csv(all_results: dict[str, list[TaskResult]]) -> str:
    """Serialize all results to CSV (one row per task-model pair)."""
    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(["task", "model", "task_score"])
    for task_name in sorted(all_results.keys()):
        for tr in all_results[task_name]:
            writer.writerow([task_name, tr.model, f"{tr.score:.4f}"])
    return buf.getvalue()

from __future__ import annotations

import argparse
import sys
from pathlib import Path


PROJECT_ROOT = Path(__file__).resolve().parents[2]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from mlsbench import scheduler  # noqa: E402


STATE_MAP = {
    "queued": "PD",
    "running": "R",
    "completed": "CD",
    "failed": "F",
    "cancelled": "CA",
}


def _effective_state(job: scheduler.Job) -> str:
    if job.state == "running" and job.pid and not scheduler._pid_exists(job.pid):
        return "ST"
    return STATE_MAP.get(job.state, job.state.upper())


def _selected_jobs(job_ids: set[int] | None = None) -> list[scheduler.Job]:
    jobs = scheduler._load_queue()
    if not job_ids:
        return jobs
    return [job for job in jobs if job.job_id in job_ids]


def _format_job_name(job: scheduler.Job) -> str:
    if job.command == "script":
        # Extract meaningful name from script path:
        # .../logs/<task>/<model>/<timestamp>/group_<g>/run.sh → <task> <model> g<g>
        from pathlib import Path
        p = Path(job.task)
        parts_list = p.parts
        try:
            logs_idx = parts_list.index("logs")
            task = parts_list[logs_idx + 1] if len(parts_list) > logs_idx + 1 else "?"
            model = parts_list[logs_idx + 2] if len(parts_list) > logs_idx + 2 else ""
            group = p.parent.name  # e.g. "group_1_0"
            return f"{task} ({model}) {group}"
        except (ValueError, IndexError):
            return f"script {p.name}"
    parts: list[str] = [job.command, job.task]
    if job.args:
        parts.append(" ".join(job.args))
    return " ".join(parts)


def _parse_job_ids(raw_values: list[str] | None) -> set[int] | None:
    if not raw_values:
        return None

    parsed: set[int] = set()
    for value in raw_values:
        for piece in value.split(","):
            piece = piece.strip()
            if not piece:
                continue
            parsed.add(int(piece))
    return parsed


def cmd_squeue(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(prog="mlsbench-squeue", description="Show queued and running MLS-Bench jobs")
    parser.add_argument("-a", "--all", action="store_true", help="Show finished jobs too")
    parser.add_argument("-j", "--jobs", action="append", help="Comma-separated job ids to include")
    parser.add_argument("--noheader", action="store_true", help="Suppress the header row")
    args = parser.parse_args(argv)

    jobs = _selected_jobs(_parse_job_ids(args.jobs))
    if not args.all:
        jobs = [job for job in jobs if _effective_state(job) in {"PD", "R", "ST"}]

    if not args.noheader:
        print(
            f"{'JOBID':>5} {'ST':<3} {'GPUS':<7} {'PID':<8} "
            f"{'TASK':<32} {'DETAILS'}"
        )
    for job in jobs:
        # For script jobs, show a short task slug instead of the full path
        if job.command == "script":
            from pathlib import Path
            p = Path(job.task)
            parts_list = p.parts
            try:
                logs_idx = parts_list.index("logs")
                task_display = parts_list[logs_idx + 1] if len(parts_list) > logs_idx + 1 else p.stem
            except ValueError:
                task_display = p.stem
        else:
            task_display = job.task
        print(
            f"{job.job_id:>5} {_effective_state(job):<3} "
            f"{(job.gpus or f'need:{job.min_gpus_needed}-{job.gpus_needed}'):<7} "
            f"{(str(job.pid) if job.pid else '-'): <8} "
            f"{task_display:<32} {_format_job_name(job)}"
        )
    return 0


def cmd_sacct(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(prog="mlsbench-sacct", description="Show MLS-Bench job history")
    parser.add_argument("-j", "--jobs", action="append", help="Comma-separated job ids to include")
    parser.add_argument("--noheader", action="store_true", help="Suppress the header row")
    args = parser.parse_args(argv)

    jobs = _selected_jobs(_parse_job_ids(args.jobs))
    if not args.noheader:
        print(
            f"{'JOBID':>5} {'STATE':<4} {'EXIT':<5} {'GPUS':<7} "
            f"{'STARTED':<19} {'FINISHED':<19} {'TASK'}"
        )
    for job in jobs:
        print(
            f"{job.job_id:>5} {_effective_state(job):<4} {job.exit_code:<5} "
            f"{(job.gpus or '-'): <7} {(job.started_at or '-'): <19} "
            f"{(job.finished_at or '-'): <19} {job.task}"
        )
    return 0


def cmd_scancel(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(prog="mlsbench-scancel", description="Cancel MLS-Bench scheduler jobs")
    parser.add_argument("job_ids", nargs="+", type=int, help="Job ids to cancel")
    args = parser.parse_args(argv)

    exit_code = 0
    for job_id in args.job_ids:
        before = {job.job_id: job.state for job in scheduler._load_queue()}
        scheduler.cmd_cancel(argparse.Namespace(job_id=job_id))
        after = {job.job_id: job.state for job in scheduler._load_queue()}
        if before.get(job_id) == after.get(job_id):
            exit_code = 1
    return exit_code


def cmd_sbatch(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(
        prog="mlsbench-sbatch",
        description="Queue an MLS-Bench scheduler job. Usage mirrors 'python scripts/scheduler.py add'.",
    )
    parser.add_argument("subcmd", choices=["agent", "baseline"])
    parser.add_argument("task")
    parser.add_argument("--model", default="claude-sonnet-4-6")
    parser.add_argument("--name", default=None)
    parser.add_argument("--seed", type=int, default=None)
    parser.add_argument("--group", type=int, action="append", default=None)
    parser.add_argument("--label", action="append", default=None)
    parser.add_argument("--config", default="configs/config.yaml")
    parser.add_argument("--gpus-needed", type=int, default=None)
    args = parser.parse_args(argv)

    scheduler.cmd_add(args)
    return 0


_COMMAND_ALIASES = {
    "squeue": "squeue", "mlsbench-squeue": "squeue",
    "sacct": "sacct", "mlsbench-sacct": "sacct",
    "scancel": "scancel", "mlsbench-scancel": "scancel",
    "sbatch": "sbatch", "mlsbench-sbatch": "sbatch",
}

_DISPATCH = {
    "squeue": cmd_squeue,
    "sacct": cmd_sacct,
    "scancel": cmd_scancel,
    "sbatch": cmd_sbatch,
}


def main(argv: list[str] | None = None) -> int:
    argv = list(argv or sys.argv[1:])
    if argv and argv[0] in _COMMAND_ALIASES:
        command = _COMMAND_ALIASES[argv.pop(0)]
    else:
        command = _COMMAND_ALIASES.get(Path(sys.argv[0]).name, Path(sys.argv[0]).name)

    handler = _DISPATCH.get(command)
    if handler:
        return handler(argv)

    print(f"Unknown command shim: {command}", file=sys.stderr)
    return 2


def squeue_main() -> None:
    raise SystemExit(main(["squeue", *sys.argv[1:]]))


def sacct_main() -> None:
    raise SystemExit(main(["sacct", *sys.argv[1:]]))


def scancel_main() -> None:
    raise SystemExit(main(["scancel", *sys.argv[1:]]))


def sbatch_main() -> None:
    raise SystemExit(main(["sbatch", *sys.argv[1:]]))


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Harbor-side verifier for MLS-Bench tasks.

Runs three sub-commands inside the agent container:

    score_task.py guard       — edit-range diff guard
    score_task.py run-evals   — execute all eval scripts (visible + hidden)
    score_task.py score       — aggregate metrics → combined_score → reward.txt

Designed to be self-contained — only stdlib, plus mlsbench installed in the
image (via the prebuilt mlsbench/<pkg> base image).
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import signal
import subprocess
import sys
import tempfile
import time
import math
from dataclasses import dataclass
from difflib import SequenceMatcher
from pathlib import Path


# --------------------------------------------------------------------------- #
# Edit-range diff guard
# --------------------------------------------------------------------------- #

@dataclass(frozen=True)
class EditRange:
    start: int  # 1-indexed inclusive; -1 means "whole file"
    end: int


def _load_task_config(task_meta: Path) -> dict:
    return json.loads((task_meta / "config.json").read_text())


def _editable_files(config: dict) -> dict[str, list[EditRange]]:
    out: dict[str, list[EditRange]] = {}
    for f in config.get("files", []):
        ranges = f.get("edit") or []
        filename = _safe_rel_path(str(f["filename"]))
        out[filename] = [EditRange(int(r["start"]), int(r["end"])) for r in ranges]
    return out


def _safe_rel_path(rel: str) -> str:
    if not rel or "\\" in rel:
        raise ValueError(f"unsafe workspace path: {rel!r}")
    p = Path(rel)
    if p.is_absolute() or any(part == ".." for part in p.parts):
        raise ValueError(f"unsafe workspace path: {rel!r}")
    return p.as_posix()


def _safe_join(root: Path, rel: str) -> Path:
    p = (root / _safe_rel_path(rel)).resolve()
    root_resolved = root.resolve()
    try:
        p.relative_to(root_resolved)
    except ValueError as exc:
        raise ValueError(f"path escapes workspace root: {rel!r}") from exc
    return p


def _check_editable_only(
    pristine: Path,
    current: Path,
    ranges: list[EditRange],
) -> tuple[bool, str | None]:
    """Return (ok, reason) for whether `current` only differs from `pristine`
    inside the given editable ranges.

    The check is content-based, not line-number-based: it splits the pristine
    file into the alternating "fixed" / "editable" segments named by `ranges`,
    then verifies every fixed segment appears verbatim, in order, inside
    `current`. Whatever lies between the matched fixed segments is treated as
    the agent's edit; we don't care how long it is. This correctly handles
    replacements that change the line count (e.g. a 7-line baseline stub
    swapped for a 30-line implementation).

    If `pristine` doesn't exist, the agent created the file; the caller does
    not treat that as a violation.
    """
    if not pristine.exists():
        return False, "new file (no pristine)"

    pristine_text = pristine.read_text()
    current_text = current.read_text() if current.exists() else ""
    if pristine_text == current_text:
        return True, None
    if any(r.start == -1 and r.end == -1 for r in ranges):
        return True, None  # whole-file editable

    pristine_lines = pristine_text.splitlines(keepends=True)
    total_lines = len(pristine_lines)

    def _end_eff(r: EditRange) -> int:
        """`end=-1` means "to EOF" — normalize for indexing comparisons."""
        return total_lines if r.end == -1 else r.end

    # Build fixed segments from pristine.
    segments: list[list[str]] = []
    cursor = 0
    for r in sorted(ranges, key=lambda r: r.start):
        if r.start - 1 > cursor:
            segments.append(pristine_lines[cursor:r.start - 1])
        cursor = _end_eff(r)
    if cursor < total_lines:
        segments.append(pristine_lines[cursor:])

    # Match the FIRST segment at the start (if the file begins with a fixed
    # segment) and the LAST segment at the end (if the file ends with one).
    # Intermediate fixed segments are anchored at their rightmost feasible
    # occurrence between the surrounding anchors. A simple left-to-right greedy
    # match can grab duplicate text from an editable region and miss deletion of
    # the real fixed segment.
    starts_with_fixed = bool(segments) and (
        sorted(ranges, key=lambda r: r.start)[0].start > 1
    )
    ends_with_fixed = bool(segments) and (
        max(_end_eff(r) for r in ranges) < total_lines
    )

    fixed = ["".join(seg) for seg in segments]
    chosen: list[tuple[int, int] | None] = [None] * len(fixed)

    if starts_with_fixed and fixed:
        first = fixed[0]
        if first and not current_text.startswith(first):
            return False, (
                "submitted file does not start with the pristine's leading "
                "fixed segment — only the declared editable range may be modified"
            )
        chosen[0] = (0, len(first))

    if ends_with_fixed and fixed:
        last = fixed[-1]
        if last and not current_text.endswith(last):
            return False, (
                "submitted file does not end with the pristine's trailing "
                "fixed segment — only the declared editable range may be modified"
            )
        chosen[-1] = (len(current_text) - len(last), len(current_text))

    # Backward pass: for each segment, compute the latest occurrence that still
    # leaves room for every later fixed segment. This prevents an earlier copy
    # inside an editable range from stealing the anchor when the real fixed
    # segment is still present later.
    suffix: list[tuple[int, int] | None] = [None] * len(fixed)
    next_start = len(current_text)
    for i in range(len(fixed) - 1, -1, -1):
        seg = fixed[i]
        if chosen[i] is not None:
            suffix[i] = chosen[i]
            next_start = chosen[i][0]
            continue
        if not seg:
            suffix[i] = (next_start, next_start)
            continue
        idx = current_text.rfind(seg, 0, next_start)
        if idx < 0:
            return False, (
                f"fixed segment #{i + 1} not found in feasible order — only "
                "the declared editable range may be modified"
            )
        suffix[i] = (idx, idx + len(seg))
        next_start = idx

    prev_end = 0
    for i, seg in enumerate(fixed):
        if chosen[i] is not None:
            start, end = chosen[i]
        else:
            assert suffix[i] is not None
            start, end = suffix[i]
        if start < prev_end:
            return False, (
                f"fixed segment #{i + 1} overlaps an earlier fixed segment — "
                "only the declared editable range may be modified"
            )
        chosen[i] = (start, end)
        prev_end = end

    # With one editable interval, the anchored pristine prefix and suffix are
    # a complete proof that every fixed byte is unchanged.  SequenceMatcher
    # can misalign a repeated boundary line (commonly a blank line) with an
    # identical line inside a replacement, then falsely report the real fixed
    # boundary as deleted.  Multiple disjoint intervals still need the
    # line-level backstop below to reject deletion of an intermediate fixed
    # segment when the editable text contains a duplicate.
    if len(ranges) == 1:
        return True, None

    editable_line_nos = {
        line_no
        for r in ranges
        for line_no in (
            range(1, total_lines + 1)
            if r.start == -1
            else range(r.start, _end_eff(r) + 1)
        )
    }
    for tag, i1, i2, _j1, _j2 in SequenceMatcher(
        None, pristine_lines, current_text.splitlines(keepends=True), autojunk=False
    ).get_opcodes():
        if tag == "equal" or tag == "insert":
            continue
        changed_fixed = [
            str(line_no)
            for line_no in range(i1 + 1, i2 + 1)
            if line_no not in editable_line_nos
        ]
        if changed_fixed:
            return False, (
                "submitted file changes pristine fixed line(s) "
                f"{', '.join(changed_fixed[:5])} — only the declared editable "
                "range may be modified"
            )

    return True, None


_SKIP_DIR_PARTS = {".git", "__pycache__", "node_modules", ".pytest_cache", ".mypy_cache"}
_SKIP_SUFFIXES = {".pyc", ".pyo", ".so", ".o", ".egg-info"}
_EXEMPT_TOP_LEVEL_DIRS = {"_task"}


def _is_workspace_guard_exempt(rel: Path) -> bool:
    return bool(rel.parts and rel.parts[0] in _EXEMPT_TOP_LEVEL_DIRS)


def _is_path_excluded(rel: Path, excludes: tuple) -> bool:
    """True if *rel* (workdir-relative) is under a config ``guard_exclude`` prefix.

    Lets a task drop image-baked data dirs (datasets / weights / caches that the
    package install bakes INSIDE the package dir, e.g. ``dbim-codebase/assets``)
    out of the guard: they are not the agent's editable source surface, the
    render-time manifest never captured them, and walking them would otherwise
    flag every baked file as a spurious ``created``/``modified`` violation
    (issue #25.2 Error-1/Error-3). POSIX path-prefix match.
    """
    if not excludes:
        return False
    rp = rel.as_posix()
    return any(rp == e or rp.startswith(e + "/") for e in excludes)


def _walk_workspace(workspace_root: Path, excludes: tuple = ()) -> set[Path]:
    out: set[Path] = set()
    if not workspace_root.exists():
        return out
    for p in workspace_root.rglob("*"):
        if not p.is_file():
            continue
        if any(part in _SKIP_DIR_PARTS for part in p.parts):
            continue
        if any(part.endswith(suf) for part in p.parts for suf in _SKIP_SUFFIXES):
            continue
        rel = p.relative_to(workspace_root)
        if _is_workspace_guard_exempt(rel):
            continue
        if _is_path_excluded(rel, excludes):
            continue
        out.add(rel)
    return out


def cmd_guard(args: argparse.Namespace) -> int:
    task_meta = Path(args.task_meta)
    config = _load_task_config(task_meta)
    # config.json::files[].filename is relative to the workdir (e.g.
    # "causal-learn/bench/custom_algorithm.py"). The pristine root holds
    # declared-file content for byte-segment matching; the manifest holds
    # sha256 for every file under any guarded prefix. Both are uploaded
    # fresh by Harbor at verify time so the agent cannot tamper with them.
    pristine_root = Path(args.pristine)
    workspace_root = Path(args.workspace)
    violation_out = Path(args.violation_out)

    manifest_path = task_meta / "pristine_manifest.json"
    if not manifest_path.exists():
        # Fail closed: missing manifest is an adapter packaging bug, but
        # silently treating it as "no constraints" lets the agent edit any
        # non-declared file. Refuse to grade.
        violation_out.parent.mkdir(parents=True, exist_ok=True)
        violation_out.write_text(
            "pristine_manifest.json missing — refusing to verify\n"
        )
        return 10
    try:
        manifest = json.loads(manifest_path.read_text())
    except json.JSONDecodeError:
        violation_out.parent.mkdir(parents=True, exist_ok=True)
        violation_out.write_text("pristine_manifest.json malformed\n")
        return 10
    if not isinstance(manifest, dict) or not manifest:
        violation_out.parent.mkdir(parents=True, exist_ok=True)
        violation_out.write_text(
            "pristine_manifest.json empty — refusing to verify\n"
        )
        return 10

    violations: list[str] = []

    editable = _editable_files(config)
    # Optional per-task allowlist of workdir-relative prefixes dropped from the
    # guard — for image-baked data/build dirs inside the package dir that aren't
    # the agent's editable surface and were never in the render-time manifest
    # (issue #25.2 Error-1/Error-3).
    guard_exclude = tuple(config.get("guard_exclude", []) or [])

    workspace_files = _walk_workspace(workspace_root, guard_exclude)
    workspace_rel_strs = {p.as_posix() for p in workspace_files}

    # Guarded prefixes: every top-level dir referenced by editable list AND
    # the manifest (covers secondary packages even if no declared edits).
    guarded_prefixes = {Path(f).parts[0] for f in editable if f}
    guarded_prefixes |= {Path(f).parts[0] for f in manifest if f}

    # Newly-created files are neither a violation nor removed. The surface this
    # guard protects is *modification* and *deletion* of the fixed baseline
    # (scorer/tests/data/model source) — both handled below. Creation is left
    # alone on purpose:
    #
    #   * Deleting them silently broke legitimate work. An agent that split its
    #     implementation into a helper module and imported it from the editable
    #     file got the helper unlinked between guard and eval, and the run died
    #     on ImportError with no way to see why.
    #   * The shadow-import risk it was meant to cover is not a capability the
    #     agent gains this way. The eval scripts import the agent's editable
    #     file in the very process that prints the metrics the parser reads
    #     (`python -u run.py` → `models/Custom.py` → `TEST_METRICS`), so
    #     arbitrary in-process code is already granted by design. Created files
    #     cannot reach the verifier either: /tests mounts only at verify time,
    #     and test.sh resets PATH and unsets every PYTHON* variable first.
    #   * The sweep needed a hand-maintained allowlist to stay correct. Every
    #     image-baked path inside a package dir had to be added to
    #     guard_exclude by hand (dbim-codebase/assets, badge/oml) because the
    #     render-time manifest never covered them; a missing entry deleted real
    #     data. Absence from the manifest never meant "the agent made this".
    #
    # `allow_create` therefore no longer changes guard behaviour; it is kept in
    # the task configs as documentation of intent.

    # Disallowed deletion: anything in manifest under a guarded prefix that
    # is gone from workspace.
    for rel_str in sorted(manifest):
        rel = Path(rel_str)
        if not rel.parts or rel.parts[0] not in guarded_prefixes:
            continue
        if _is_path_excluded(rel, guard_exclude):
            continue
        if rel_str in workspace_rel_strs:
            continue
        if rel_str in editable:
            # Declared editable files: treat deletion as a range violation
            # so the existing logic below produces a more specific message.
            continue
        violations.append(f"deleted file: {rel_str}")

    # Edit-range checks for files declared with allowed-edit ranges.
    for rel_name, ranges in editable.items():
        cur = _safe_join(workspace_root, rel_name)
        pri = _safe_join(pristine_root, rel_name)
        if not pri.exists():
            # Adapter packaging bug — every declared file should have a
            # pristine. Whole-file editable still requires the file to
            # exist in workspace; missing pristine cannot excuse deletion.
            if any(r.start == -1 and r.end == -1 for r in ranges):
                if not cur.exists():
                    violations.append(
                        f"{rel_name}: deleted (whole-file editable but missing in workspace)"
                    )
                continue
            violations.append(f"{rel_name}: pristine snapshot missing in tests/meta/pristine")
            continue
        if not ranges:
            # Declared read-only.
            if cur.exists() and cur.read_text() != pri.read_text():
                violations.append(f"{rel_name}: modified but file is declared read-only")
            elif not cur.exists():
                violations.append(f"{rel_name}: deleted but file is declared read-only")
            continue
        if not cur.exists():
            violations.append(f"{rel_name}: deleted (file declared with editable range)")
            continue
        ok, reason = _check_editable_only(pri, cur, ranges)
        if not ok:
            violations.append(f"{rel_name}: {reason}")

    # Modifications to files NOT declared in config.json::files[] but under a
    # guarded prefix: hash-compare against the manifest. Binary-safe.
    for rel in sorted(workspace_files):
        rel_str = rel.as_posix()
        if rel_str in editable:
            continue
        if not rel.parts or rel.parts[0] not in guarded_prefixes:
            continue
        expected_sha = manifest.get(rel_str)
        if expected_sha is None:
            # Newly created file — not tracked, not a violation.
            continue
        try:
            actual = hashlib.sha256(
                _safe_join(workspace_root, rel_str).read_bytes()
            ).hexdigest()
        except OSError:
            continue
        if actual != expected_sha:
            violations.append(f"{rel_str}: modified but not in editable file list")

    if violations:
        violation_out.parent.mkdir(parents=True, exist_ok=True)
        violation_out.write_text("\n".join(violations) + "\n")
        return 10
    return 0


# --------------------------------------------------------------------------- #
# Run all eval scripts (visible + hidden)
# --------------------------------------------------------------------------- #

_ENV_VAR_RE = re.compile(r"\$(\w+)|\$\{([^}:]+)(?::-[^}]*)?\}")


def _read_meta_text(task_meta: Path, name: str, default: str = "") -> str:
    p = task_meta / name
    if not p.exists():
        return default
    return p.read_text().strip() or default


def _expand_env_template(value: str, base_env: dict[str, str]) -> str:
    def repl(match):
        name = match.group(1) or match.group(2) or ""
        return base_env.get(name, "")

    return _ENV_VAR_RE.sub(repl, value)


def _load_package_envs(task_meta: Path) -> dict[str, dict[str, str]]:
    p = task_meta / "package_envs.json"
    if not p.exists():
        return {}
    try:
        raw = json.loads(p.read_text())
    except json.JSONDecodeError:
        return {}
    return {
        str(pkg): {str(k): str(v) for k, v in env.items()}
        for pkg, env in raw.items()
        if isinstance(env, dict)
    }


def _package_dir(workspace_root: Path, default_pkg: str, tc: dict) -> Path:
    pkg = str(tc.get("package") or default_pkg)
    candidate = workspace_root / pkg
    if candidate.exists():
        return candidate
    norm = _normalize_pkg_name(pkg)
    if workspace_root.exists():
        for child in workspace_root.iterdir():
            if child.is_dir() and _normalize_pkg_name(child.name) == norm:
                return child
    return workspace_root / default_pkg


def _normalize_pkg_name(name: str) -> str:
    return str(name).lower().replace("-", "").replace("_", "")


# Thread-pool knobs every scientific-Python stack reads at import time.
# Mirrors ``_LOCAL_THREAD_ENV_KEYS`` in ``mlsbench/cli.py`` so a Harbor run and
# a native local run size their thread pools the same way.
_THREAD_ENV_KEYS = (
    "OMP_NUM_THREADS",
    "OMP_THREAD_LIMIT",
    "MKL_NUM_THREADS",
    "OPENBLAS_NUM_THREADS",
    "NUMEXPR_NUM_THREADS",
    "NUMEXPR_MAX_THREADS",
    "VECLIB_MAXIMUM_THREADS",
    "BLIS_NUM_THREADS",
)


def _cgroup_cpu_quota() -> float | None:
    """CPUs this container's cgroup actually grants, or None if unlimited."""
    try:
        fields = Path("/sys/fs/cgroup/cpu.max").read_text().split()
        if len(fields) == 2 and fields[0] != "max":
            period = int(fields[1])
            if period > 0:
                return int(fields[0]) / period
    except (OSError, ValueError):
        pass
    try:
        quota = int(Path("/sys/fs/cgroup/cpu/cpu.cfs_quota_us").read_text())
        period = int(Path("/sys/fs/cgroup/cpu/cpu.cfs_period_us").read_text())
        if quota > 0 and period > 0:
            return quota / period
    except (OSError, ValueError):
        pass
    return None


def _available_cpus() -> int:
    """Cores usable here — the cgroup quota, not what ``nproc`` advertises.

    Harbor turns ``task.toml``'s ``cpus`` into a hard cgroup limit (local
    Docker via ``deploy.resources.limits``, Daytona via the sandbox's
    resources), but ``/proc/cpuinfo`` still lists every host core.  Libraries
    that size their pools from ``os.cpu_count()`` therefore start one thread
    per host core and burn the quota on context switches.
    """
    try:
        affinity = len(os.sched_getaffinity(0))
    except (AttributeError, OSError):
        affinity = os.cpu_count() or 1
    quota = _cgroup_cpu_quota()
    if quota is None:
        return max(1, affinity)
    return max(1, min(affinity, int(quota)))


def _thread_budget(concurrency: int = 1) -> int:
    """Per-process thread budget, split across concurrently running commands."""
    override = os.environ.get("MLSBENCH_LOCAL_THREADS", "").strip()
    if override:
        try:
            return max(1, int(override))
        except ValueError:
            pass
    return max(1, _available_cpus() // max(1, concurrency))


def _eval_env(
    *,
    task_meta: Path,
    out_dir: Path,
    workspace_root: Path,
    pkg_dir: Path,
    tc: dict,
    seed: int,
    threads: int | None = None,
) -> dict[str, str]:
    env = os.environ.copy()
    # Size the thread pools against the cgroup quota before the package and
    # command environments are layered on, so a task that deliberately sets
    # one of these keys still wins.
    budget = str(threads if threads is not None else _thread_budget())
    for key in _THREAD_ENV_KEYS:
        env[key] = budget
    default_pkg = _read_meta_text(task_meta, "package", "")
    package_envs = _load_package_envs(task_meta)
    pkg_name = str(tc.get("package") or default_pkg)
    for key, value in package_envs.get(pkg_name, package_envs.get(default_pkg, {})).items():
        if key == "HOME":
            env[key] = value
        else:
            env[key] = _expand_env_template(value, env)

    # Command-specific environment overrides (including the materialized
    # H200 block) must reach the actual eval subprocess.  Keep this after the
    # package defaults so a task command can intentionally specialize them,
    # and expand templates against the already-populated environment.
    for key, value in (tc.get("env") or {}).items():
        key = str(key)
        value = str(value)
        env[key] = _expand_env_template(value, env)

    task_id = _read_meta_text(task_meta, "task_id", "unknown")
    save_path = out_dir / "save"
    output_dir = save_path / task_id / "harbor" / f"seed_{seed}"
    output_dir.mkdir(parents=True, exist_ok=True)

    env["SAVE_PATH"] = str(save_path)
    env["OUTPUT_DIR"] = str(output_dir)
    env["SEED"] = str(seed)
    label = str(tc.get("label", ""))
    if label:
        env["ENV"] = label
    env["MLSBENCH_TASK_DIR"] = str(task_meta)
    env["MLSBENCH_PKG_DIR"] = str(pkg_dir)
    env.setdefault("DATA_ROOT", "/data")
    env["MLSBENCH_LOCAL_PATH_MAP_JSON"] = json.dumps({
        "/workspace": str(workspace_root),
        f"/workspace/{pkg_name}": str(pkg_dir),
        "/data": "/data",
    })
    return env


def _parse_time_to_seconds(time_str: str) -> int:
    parts = str(time_str).split(":")
    try:
        if len(parts) == 3:
            return int(parts[0]) * 3600 + int(parts[1]) * 60 + int(parts[2])
        if len(parts) == 2:
            return int(parts[0]) * 60 + int(parts[1])
        return int(float(parts[0]))
    except (ValueError, IndexError):
        return 3600


def _test_cmd_compute(tc: dict) -> float:
    try:
        return float(tc.get("compute", 1) or 1)
    except (TypeError, ValueError):
        return 1.0


def _running_gpu_is_h200() -> bool:
    """Return whether this verifier is running on an H200-class GPU.

    MLS-Bench's native runner selects the H200-specific command block only
    through an explicit host setting (``compute_scale: 0.5``); it never
    auto-detects the device.  Harbor mirrors that: the provider (for example
    the Daytona adapter, via ``--ek gpu_type=H200``) must export
    ``MLSBENCH_GPU_TYPE=H200``.  Running the baseline command on an H200 host
    without that variable keeps the H100 profile, exactly like native runs.
    """
    raw = os.environ.get("MLSBENCH_GPU_TYPE", "").strip()
    return "H200" in raw.upper()


def _effective_test_cmds(config: dict) -> list[dict]:
    """Materialize hardware-specific test command overrides.

    The ``h200`` blocks are deliberately metadata in the public task config:
    they are selected only when an H200 is really attached.  Keep the original
    dictionaries untouched so the verifier's budget and scheduling code sees
    one consistent, fully materialized command list.
    """
    entries = [dict(tc) for tc in (config.get("test_cmds", []) or [])]
    if not _running_gpu_is_h200():
        return entries
    for entry in entries:
        override = entry.pop("h200", None)
        if not isinstance(override, dict):
            continue
        if "cmd" in override:
            entry["cmd"] = override["cmd"]
        if "compute" in override:
            entry["compute"] = override["compute"]
        if override.get("env"):
            env = dict(entry.get("env") or {})
            env.update(override["env"])
            entry["env"] = env
    return entries


def _config_seeds(config: dict) -> list[int]:
    seeds = config.get("seeds") or [42]
    if isinstance(seeds, int):
        seeds = [seeds]
    return sorted(int(seed) for seed in seeds)


def _group_entries(test_cmds: list[dict]) -> dict[int, list[tuple[int, dict]]]:
    auto_group = 10000
    grouped: dict[int, list[tuple[int, dict]]] = {}
    for idx, entry in enumerate(test_cmds):
        group = entry.get("group")
        if group is None:
            group = auto_group
            auto_group += 1
        grouped.setdefault(group, []).append((idx, entry))
    return grouped


# Peak GPUs a task may reserve; groups that want more at once are run as
# sequential waves of at most this many GPUs. Only consulted when
# tests/meta/gpu_count is missing — the rendered value is authoritative. Keep in
# sync with `MAX_PARALLEL_GPUS` in harbor_adapter/src/mls_bench/adapter.py.
MAX_PARALLEL_GPUS = 8

# Grace added to every wave's deadline. adapter.py::_verifier_timeout_sec
# charges the same amount per wave, so the outer verifier budget can never be
# tighter than the deadlines this runner hands out.
WAVE_GRACE_SEC = 300
# Gap between the launches of one wave's commands. They share a workspace and
# a first-use initialization (an mlflow store, a compile cache, a font cache)
# that is not always locked; a second between starts keeps those from
# landing in the same instant without changing the wave's deadline.
WAVE_LAUNCH_STAGGER_SEC = 1.0
# After a wave in which a command was killed at its deadline, wait this long
# before starting the next one. A killed torchrun leaves its rendezvous port
# in TIME_WAIT for the kernel's 60 s; the next group of cv-diffusion-*
# derives the same port from the task name and died 3 s later with
# EADDRINUSE (Modal sweep, 2026-09-09), turning one timeout into two.
WAVE_KILL_SETTLE_SEC = 65


def _bin_pack_fractional_gpus(fractionals: list[float]) -> int:
    """Min 1.0-capacity bins needed for these fractional GPU jobs.

    First-fit-decreasing. `ceil(sum)` underestimates whenever per-GPU capacity
    is bin-limited (e.g. 9 jobs of 0.4 GPUs each need 5 bins, not ceil(3.6)=4,
    because each bin holds at most floor(1/0.4)=2 such jobs).
    """
    bins: list[float] = []
    for c in sorted(fractionals, reverse=True):
        for i, cap in enumerate(bins):
            if cap >= c:
                bins[i] = cap - c
                break
        else:
            bins.append(1.0 - c)
    return len(bins)


def _peak_gpu_usage(computes: list[float]) -> int:
    """GPUs needed to run every job in *computes* at once."""
    whole = sum(max(1, math.ceil(c)) for c in computes if c >= 1.0)
    return whole + _bin_pack_fractional_gpus([c for c in computes if 0.0 < c < 1.0])


def _split_computes_into_waves(computes: list[float], devices: int) -> list[list[float]]:
    """Greedy contiguous batching, same order as _partition_group_gpu_batches."""
    waves: list[list[float]] = []
    current: list[float] = []
    for compute in computes:
        if current and _peak_gpu_usage([*current, compute]) > devices:
            waves.append(current)
            current = [compute]
        else:
            current.append(compute)
    if current:
        waves.append(current)
    return waves


def _wave_balanced_gpus(
    computes: list[float],
    peak_gpus: int,
    largest_job: int,
) -> int:
    """Widest reservation <= MAX_PARALLEL_GPUS whose waves are all equally full.

    Mirrors adapter.py::_wave_balanced_gpus; see the rationale there.
    """
    if peak_gpus <= MAX_PARALLEL_GPUS:
        return peak_gpus
    for candidate in range(MAX_PARALLEL_GPUS, largest_job - 1, -1):
        usage = [
            _peak_gpu_usage(wave) for wave in _split_computes_into_waves(computes, candidate)
        ]
        if usage and len(set(usage)) == 1:
            return usage[0]
    return largest_job


def _infer_reserved_gpu_count(config: dict) -> int:
    if config.get("use_cuda") is False:
        return 0
    test_cmds = list(config.get("test_cmds", []) or [])
    if not config.get("use_cuda") and not any("compute" in tc for tc in test_cmds):
        return 0

    peak_gpus = 0
    largest_job = 0
    peak_computes: list[float] = []
    n_seeds = max(1, len(_config_seeds(config)))
    for entries in _group_entries(test_cmds).values():
        whole = 0
        fractionals: list[float] = []
        computes: list[float] = []
        for _, tc in entries:
            compute = _test_cmd_compute(tc)
            computes.extend([compute] * n_seeds)
            if compute > 0.0:
                largest_job = max(largest_job, max(1, math.ceil(compute)))
            if compute >= 1.0:
                whole += n_seeds * max(1, math.ceil(compute))
            elif compute > 0.0:
                fractionals.extend([compute] * n_seeds)
        group_peak = whole + _bin_pack_fractional_gpus(fractionals)
        if group_peak >= peak_gpus:
            peak_computes = computes
        peak_gpus = max(peak_gpus, group_peak)
    if not peak_gpus:
        return 0
    # Same rule the adapter applies when rendering tests/meta/gpu_count: a group
    # wanting more GPUs at once than MAX_PARALLEL_GPUS runs as sequential waves
    # (see _partition_group_gpu_batches), and the reservation is the widest one
    # at or below the cap that every wave fills. Clamping straight to the cap
    # would leave the final wave holding idle GPUs — three 4-GPU jobs on 8
    # reserved run as waves of 2 and 1, costing more GPU-hours than reserving 4
    # and more wall clock than reserving 12.
    return max(1, _wave_balanced_gpus(peak_computes, peak_gpus, largest_job), largest_job)


def _reserved_gpu_count(task_meta: Path, config: dict) -> int:
    p = task_meta / "gpu_count"
    if p.exists():
        try:
            return max(0, int(p.read_text().strip() or "0"))
        except ValueError:
            pass
    return _infer_reserved_gpu_count(config)


def _visible_gpu_indices(task_meta: Path, config: dict) -> list[str]:
    reserved = _reserved_gpu_count(task_meta, config)
    if reserved <= 0:
        return []

    # Source-of-truth ordering inside the container:
    #   1. nvidia-smi — reflects what nvidia-container-runtime actually
    #      attached via docker-compose `deploy.resources.reservations`.
    #      Authoritative.
    #   2. CUDA_VISIBLE_DEVICES env var — many base images (pytorch/conda)
    #      pre-set this to "0" as a single-GPU default. Trusting that
    #      env var would silently cap our scheduler at 1 GPU even when
    #      docker actually exposes more. Only use as a fallback when
    #      nvidia-smi is unavailable.
    #   3. range(reserved) — last-resort fallback.
    try:
        out = subprocess.run(
            ["nvidia-smi", "--query-gpu=index", "--format=csv,noheader"],
            capture_output=True,
            text=True,
            timeout=10,
            check=False,
        )
        devices = [line.strip() for line in out.stdout.splitlines() if line.strip()]
        if devices:
            return devices[:reserved]
    except Exception:
        pass

    raw = os.environ.get("CUDA_VISIBLE_DEVICES", "")
    if raw and raw.lower() not in {"all", "none", "void", "-1"}:
        devices = [d.strip() for d in raw.split(",") if d.strip()]
        if devices:
            return devices[:reserved]

    return [str(i) for i in range(reserved)]


def _task_gpu_need(task: dict) -> int:
    compute = _test_cmd_compute(task["entry"]["tc"])
    if compute <= 0.0:
        return 0
    if compute >= 1.0:
        return max(1, math.ceil(compute))
    return 1


def _try_allocate_task_to_remaining(
    task: dict,
    remaining: dict[str, float],
) -> str | None:
    compute = _test_cmd_compute(task["entry"]["tc"])
    if compute <= 0.0:
        return None
    if compute >= 1.0:
        need = max(1, math.ceil(compute))
        free = [device for device, cap in remaining.items() if cap >= 1.0]
        if len(free) < need:
            return None
        chosen = free[:need]
        for device in chosen:
            remaining[device] = 0.0
        return ",".join(chosen)

    chosen = next((device for device, cap in remaining.items() if cap >= compute), None)
    if chosen is None:
        return None
    remaining[chosen] -= compute
    return chosen


def _allocate_group_gpu_assignments(
    tasks: list[dict],
    devices: list[str],
) -> list[str | None] | None:
    if not devices:
        return [None] * len(tasks)

    assignments: list[str | None] = [None] * len(tasks)
    remaining = {device: 1.0 for device in devices}
    indexed = list(enumerate(tasks))
    indexed.sort(
        key=lambda item: (
            0 if _test_cmd_compute(item[1]["entry"]["tc"]) >= 1.0 else 1
        )
    )

    for idx, task in indexed:
        assignment = _try_allocate_task_to_remaining(task, remaining)
        if assignment is None and _task_gpu_need(task) > 0:
            return None
        assignments[idx] = assignment
    return assignments


def _partition_group_gpu_batches(
    tasks: list[dict],
    devices: list[str],
) -> list[tuple[list[dict], list[str | None]]] | None:
    if not devices:
        return [(list(tasks), [None] * len(tasks))]

    batches: list[tuple[list[dict], list[str | None]]] = []
    current: list[dict] = []
    for task in tasks:
        trial = [*current, task]
        if _allocate_group_gpu_assignments(trial, devices) is None:
            if not current:
                return None
            assignments = _allocate_group_gpu_assignments(current, devices)
            if assignments is None:
                return None
            batches.append((current, assignments))
            current = [task]
            if _allocate_group_gpu_assignments(current, devices) is None:
                return None
        else:
            current = trial

    if current:
        assignments = _allocate_group_gpu_assignments(current, devices)
        if assignments is None:
            return None
        batches.append((current, assignments))
    return batches


def _process_group_alive(pgid: int) -> bool:
    try:
        os.killpg(pgid, 0)
        return True
    except PermissionError:
        return True
    except OSError:
        return False


def _kill_process_group(pgid: int, timeout: float = 30.0) -> None:
    try:
        os.killpg(pgid, signal.SIGTERM)
    except OSError:
        return

    deadline = time.time() + timeout
    while time.time() < deadline:
        if not _process_group_alive(pgid):
            return
        time.sleep(0.5)

    try:
        os.killpg(pgid, signal.SIGKILL)
    except OSError:
        pass


def _copy_task_meta_for_budget(
    task_meta: Path, scratch_dir: Path,
    effective_test_cmds: list[dict] | None = None,
    eval_root: Path | None = None,
) -> Path:
    """Stage a private copy of the task for budget_check.py; return its task dir.

    The copy keeps the native checkout's relative layout,
    ``<scratch>/tasks/<task_id>/`` beside ``<scratch>/holdout/<task_id>/``,
    because ``edits/mid_edit.py`` resolves the verifier-only input generator
    as ``parents[3] / "holdout" / <task_id>`` (native runs the budget check of
    ephemeral-input tasks host-side against exactly such a snapshot).  The
    holdout copy is ``<eval_root>/_inputgen/holdout/<task_id>`` when the bundle
    ships one, the same files apply.py imports at eval time.  A flat scratch
    dir made that path ``/holdout/<task_id>``, so optimization-nas's check
    died on import and every eval failed with rc=1.
    """
    task_id = _read_meta_text(task_meta, "task_id", "task")
    task_dir = scratch_dir / "tasks" / task_id
    task_dir.mkdir(parents=True, exist_ok=True)
    for name in ("config.json", "budget_check.py"):
        src = task_meta / name
        if src.exists():
            shutil.copy2(src, task_dir / name)
    for name in ("edits", "scripts"):
        src = task_meta / name
        if src.exists():
            shutil.copytree(src, task_dir / name, dirs_exist_ok=True)
    if eval_root is not None:
        holdout_src = eval_root / "_inputgen" / "holdout" / task_id
        if holdout_src.is_dir():
            shutil.copytree(
                holdout_src, scratch_dir / "holdout" / task_id, dirs_exist_ok=True
            )
    # budget_check.py derives the agent model's hyperparameters from this
    # config.json's test_cmds (active_test_cmd -> cmd -> expand_script_argv). For
    # an oracle run the eval cmd is replaced by the strongest baseline's cmd, and
    # that substitution MUST be reflected here too — otherwise the budget check
    # counts the agent model under the ORIGINAL (large) eval-script
    # hyperparameters and wrongly rejects the oracle baseline (all-zero TS
    # oracle). Native MLSBench runs the budget check against the
    # baseline-substituted task config; mirror that.
    if effective_test_cmds is not None:
        cfg_path = task_dir / "config.json"
        if cfg_path.exists():
            cfg = json.loads(cfg_path.read_text())
            cfg["test_cmds"] = effective_test_cmds
            cfg_path.write_text(json.dumps(cfg, indent=2))
    return task_dir


def _install_budget_legacy_links(scratch_dir: Path, workspace_root: Path) -> list[Path]:
    links: list[Path] = []
    for dst in {workspace_root / "_task", Path("/workspace/_task")}:
        try:
            if dst.exists() or dst.is_symlink():
                if dst.is_dir() and not dst.is_symlink():
                    shutil.rmtree(dst)
                else:
                    dst.unlink()
            dst.parent.mkdir(parents=True, exist_ok=True)
            os.symlink(scratch_dir, dst, target_is_directory=True)
            links.append(dst)
        except OSError:
            continue
    return links


def _remove_budget_legacy_links(links: list[Path]) -> None:
    for link in links:
        try:
            if link.is_symlink():
                link.unlink()
        except OSError:
            pass


def _build_eval_task_dir(task_meta: Path) -> Path:
    """Throwaway dir exposing ONLY the eval-time resources (scripts/ data/
    third_party/) that some eval wrappers reach via /workspace/_task or
    $MLSBENCH_TASK_DIR. It deliberately EXCLUDES the scoring metadata
    (parser.py / score_spec.py / config.json / leaderboard.csv) that cmd_score
    imports: eval runs agent-authored package code as root, so any path it can
    reach is writable (chmod a-w doesn't stop root), and exposing the real
    task_meta would let a submission overwrite the parser/spec before the score
    phase. The real task_meta stays at its unexposed random /tmp path."""
    d = Path(tempfile.mkdtemp(prefix="mlsbench-evaltask-"))
    for sub in ("scripts", "data", "third_party"):
        src = task_meta / sub
        if src.exists():
            shutil.copytree(src, d / sub, dirs_exist_ok=True)
    # `task_description.md` lands at the root: an eval that resolves its task
    # directory walks up from its own path until it finds that file. It is the
    # only thing the renderer stages here (see EVALTASK_FILES) — the native
    # task dir's `baselines/` holds the reference implementations.
    extras = task_meta / "evaltask"
    if extras.exists():
        for entry in extras.iterdir():
            if entry.is_dir():
                shutil.copytree(entry, d / entry.name, dirs_exist_ok=True)
            else:
                shutil.copy2(entry, d / entry.name)
    return d


def _run_budget_check(
    *,
    task_meta: Path,
    workspace_root: Path,
    pkg_dir: Path,
    out_dir: Path,
    label: str,
    seed: int,
    env: dict[str, str],
    effective_test_cmds: list[dict] | None = None,
    eval_root: Path | None = None,
) -> dict | None:
    if not (task_meta / "budget_check.py").exists():
        return None
    log_path = out_dir / f"{label}__seed{seed}__budget_check.log"
    # Use the same hardened interpreter as test.sh — MLSBENCH_VERIFIER_PYTHON
    # is exported by test.sh after PATH reset; falls back to sys.executable
    # (which is itself a hardened interpreter since we run under test.sh).
    python_bin = os.environ.get("MLSBENCH_VERIFIER_PYTHON") or sys.executable
    # Note: NOT using -I here because budget_check.py may legitimately need
    # PYTHONPATH from the package env (e.g. to import the model defined under
    # /workspace/<pkg>/). We rely on the env dict being verifier-controlled
    # — test.sh stripped agent-planted PYTHONPATH before this script runs.
    safe_label = re.sub(r"[^A-Za-z0-9_.-]+", "-", label)[:64] or "test"
    scratch_dir = Path(tempfile.mkdtemp(prefix=f"mlsbench-budget-{safe_label}-{seed}-"))
    legacy_links: list[Path] = []
    with log_path.open("w") as fh:
        try:
            task_dir = _copy_task_meta_for_budget(
                task_meta, scratch_dir, effective_test_cmds, eval_root=eval_root
            )
            legacy_links = _install_budget_legacy_links(task_dir, workspace_root)
            budget_env = env.copy()
            budget_env["TMPDIR"] = str(scratch_dir)
            budget_env["MLSBENCH_TASK_DIR"] = str(task_dir)
            proc = subprocess.run(
                [python_bin, str(task_dir / "budget_check.py")],
                cwd=str(pkg_dir),
                env=budget_env,
                stdout=fh,
                stderr=subprocess.STDOUT,
                timeout=120,
                check=False,
            )
            rc = proc.returncode
        except subprocess.TimeoutExpired:
            fh.write("\n[BUDGET CHECK TIMEOUT] budget_check.py took >120s\n")
            rc = 124
        except Exception as exc:
            fh.write(f"\n[BUDGET CHECK ERROR] {exc}\n")
            rc = 125
        finally:
            _remove_budget_legacy_links(legacy_links)
            shutil.rmtree(scratch_dir, ignore_errors=True)
    return {"rc": rc, "log": str(log_path)}


def _eval_log_path(out_dir: Path, label: str, seed: int) -> Path:
    return out_dir / f"{label}__seed{seed}.log"


def _write_error_record(
    out_dir: Path,
    entry: dict,
    seed: int,
    message: str,
    rc: int,
) -> dict:
    log_path = _eval_log_path(out_dir, entry["label"], seed)
    log_path.write_text(message.rstrip() + "\n")
    return {
        "seed": seed,
        "rc": rc,
        "log": str(log_path),
        "elapsed": 0.0,
    }


def _finish_process_record(state: dict, seed: int, rc: int | None = None) -> dict:
    if rc is None:
        rc = state["proc"].returncode
    if rc is None:
        rc = 124
    elapsed = time.time() - state["start"]
    try:
        state["fh"].close()
    except OSError:
        pass
    return {
        "seed": seed,
        "rc": rc,
        "log": str(state["log_path"]),
        "elapsed": elapsed,
    }


def _run_eval_wave(
    *,
    tasks: list[dict],
    assignments: list[str | None],
    task_meta: Path,
    workspace_root: Path,
    default_pkg: str,
    out_dir: Path,
) -> dict[tuple[int, int], dict]:
    timeout_secs = int(
        max(
            _parse_time_to_seconds(task["entry"]["tc"].get("time", "1:00:00"))
            for task in tasks
        )
    ) + WAVE_GRACE_SEC
    deadline = time.time() + timeout_secs
    running: list[dict] = []
    results: dict[tuple[int, int], dict] = {}
    # Everything in a wave runs at once, so each command gets a share of the
    # CPU quota rather than all of it.
    threads = _thread_budget(len(tasks))

    for launch_index, (task, gpu_devices) in enumerate(zip(tasks, assignments)):
        if launch_index:
            time.sleep(WAVE_LAUNCH_STAGGER_SEC)
        entry = task["entry"]
        seed = int(task["seed"])
        log_path = _eval_log_path(out_dir, entry["label"], seed)
        pkg_dir = _package_dir(workspace_root, default_pkg, entry["tc"])
        env = _eval_env(
            task_meta=task_meta,
            out_dir=out_dir,
            workspace_root=workspace_root,
            pkg_dir=pkg_dir,
            tc=entry["tc"],
            seed=seed,
            threads=threads,
        )
        if gpu_devices:
            env["CUDA_VISIBLE_DEVICES"] = gpu_devices
            env["NVIDIA_VISIBLE_DEVICES"] = gpu_devices
        fh = log_path.open("w")
        t_start = time.time()
        try:
            proc = subprocess.Popen(
                ["bash", str(entry["script"])],
                cwd=str(pkg_dir),
                env=env,
                stdout=fh,
                stderr=subprocess.STDOUT,
                start_new_session=True,
            )
        except Exception as exc:
            fh.write(f"[ERROR] failed to start eval command: {exc}\n")
            fh.close()
            results[(entry["idx"], seed)] = {
                "seed": seed,
                "rc": 127,
                "log": str(log_path),
                "elapsed": time.time() - t_start,
            }
            continue
        running.append({
            "entry": entry,
            "seed": seed,
            "proc": proc,
            "fh": fh,
            "start": t_start,
            "log_path": log_path,
        })

    while running and time.time() < deadline:
        still_running: list[dict] = []
        for state in running:
            rc = state["proc"].poll()
            if rc is None:
                still_running.append(state)
            else:
                results[(state["entry"]["idx"], state["seed"])] = _finish_process_record(
                    state,
                    state["seed"],
                    rc,
                )
        running = still_running
        if running:
            time.sleep(0.5)

    for state in running:
        try:
            state["fh"].write(
                f"\n[TIMEOUT] Command timed out after {timeout_secs} seconds.\n"
            )
            state["fh"].flush()
        except OSError:
            pass
        _kill_process_group(state["proc"].pid, timeout=30.0)
        try:
            state["proc"].wait(timeout=1)
        except Exception:
            pass
        results[(state["entry"]["idx"], state["seed"])] = _finish_process_record(
            state,
            state["seed"],
            124,
        )

    return results


def _parse_oracle_cmd_overrides(raw: str | None) -> list[dict]:
    if not raw:
        return []
    try:
        data = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid oracle cmd overrides JSON: {exc}") from exc
    if not isinstance(data, list):
        raise ValueError("oracle cmd overrides must be a JSON list")

    out: list[dict] = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("oracle cmd override entries must be objects")
        cmd = str(item.get("cmd", "")).strip()
        env = item.get("env")
        if env is not None and not isinstance(env, dict):
            raise ValueError("oracle cmd override env must be an object")
        env = {str(k): str(v) for k, v in (env or {}).items()}
        if not cmd and not env:
            raise ValueError("oracle cmd override needs a non-empty cmd or env")
        override: dict = {}
        if cmd:
            override["cmd"] = cmd
        if env:
            override["env"] = env
        if "labels" in item:
            labels = item.get("labels") or [""]
            if not isinstance(labels, list):
                labels = [labels]
            out.extend({"label": str(label), **override} for label in labels)
        else:
            out.append({"label": str(item.get("label", "")), **override})
    return out


def _apply_oracle_cmd_overrides(
    test_cmds: list[dict],
    overrides: list[dict],
) -> list[dict]:
    result = [dict(tc) for tc in test_cmds]
    for override in overrides:
        label = override["label"]
        for entry in result:
            if not label or str(entry.get("label", "")) == label:
                if override.get("cmd"):
                    entry["cmd"] = override["cmd"]
                if override.get("env"):
                    # Baseline env (native cli exports baseline_config["env"])
                    # reaches the eval subprocess through tc["env"].
                    merged = dict(entry.get("env") or {})
                    merged.update(override["env"])
                    entry["env"] = merged
    return result


def cmd_run_evals(args: argparse.Namespace) -> int:
    task_meta = Path(args.task_meta)
    workspace_root = Path(args.workspace)
    default_pkg = _read_meta_text(task_meta, "package", "")
    eval_root = Path(args.eval_root)
    out_dir = Path(args.out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    config = _load_task_config(task_meta)
    # Select an H200-specific command/env/compute override when the verifier
    # is actually running on H200 hardware.  This keeps Harbor's direct
    # sandbox behavior aligned with MLS-Bench's native ``compute_scale=0.5``
    # path and, importantly, applies the same materialized list to budget
    # checks, GPU packing, and the eval subprocesses.
    test_cmds = _effective_test_cmds(config)
    oracle_cmd_overrides = _parse_oracle_cmd_overrides(
        getattr(args, "oracle_cmd_overrides", None)
    )
    if oracle_cmd_overrides:
        test_cmds = _apply_oracle_cmd_overrides(test_cmds, oracle_cmd_overrides)
    seeds = _config_seeds(config)

    summary = [
        {"label": tc.get("label", tc.get("cmd", "test")), "hidden": bool(tc.get("hidden")), "logs": []}
        for tc in test_cmds
    ]
    records: dict[tuple[int, int], dict] = {}
    prepared: dict[int, dict] = {}
    for idx, tc in enumerate(test_cmds):
        cmd_rel = tc.get("cmd", "")
        label = tc.get("label", cmd_rel)
        # _safe_join rejects absolute paths, `..` traversal, and Windows
        # backslashes — without it, a hostile config could point at
        # /workspace/payload.sh and run agent-controlled code as verifier.
        try:
            script = Path(_safe_join(eval_root, cmd_rel))
        except ValueError as exc:
            entry = {"idx": idx, "tc": tc, "label": label}
            for seed in seeds:
                records[(idx, seed)] = _write_error_record(
                    out_dir,
                    entry,
                    seed,
                    f"[ERROR] unsafe_cmd_path: {exc}",
                    126,
                )
            continue
        if not script.exists():
            entry = {"idx": idx, "tc": tc, "label": label}
            for seed in seeds:
                records[(idx, seed)] = _write_error_record(
                    out_dir,
                    entry,
                    seed,
                    f"[ERROR] missing_script: {cmd_rel}",
                    127,
                )
            continue
        prepared[idx] = {"idx": idx, "tc": tc, "label": label, "script": script}

    grouped = _group_entries(test_cmds)
    devices = _visible_gpu_indices(task_meta, config)
    n_reserved = len(devices)

    for group_key in sorted(grouped.keys()):
        group_entries = [
            prepared[idx]
            for idx, _ in grouped[group_key]
            if idx in prepared
        ]
        if not group_entries:
            continue

        group_tasks = [
            {"entry": entry, "seed": seed}
            for entry in group_entries
            for seed in seeds
        ]

        schedulable: list[dict] = []
        for task in group_tasks:
            entry = task["entry"]
            seed = int(task["seed"])
            need = _task_gpu_need(task)
            if n_reserved > 0 and need > n_reserved:
                records[(entry["idx"], seed)] = _write_error_record(
                    out_dir,
                    entry,
                    seed,
                    (
                        "[ERROR] test_cmd compute requires "
                        f"{need} GPUs but only {n_reserved} reserved/visible"
                    ),
                    125,
                )
            else:
                schedulable.append(task)

        if not schedulable:
            continue

        batches = _partition_group_gpu_batches(schedulable, devices)
        if batches is None:
            for task in schedulable:
                entry = task["entry"]
                seed = int(task["seed"])
                records[(entry["idx"], seed)] = _write_error_record(
                    out_dir,
                    entry,
                    seed,
                    (
                        "[ERROR] unable to allocate GPUs for test_cmd "
                        f"with compute={_test_cmd_compute(entry['tc'])}"
                    ),
                    125,
                )
            continue

        for wave_tasks, assignments in batches:
            runnable_tasks: list[dict] = []
            runnable_assignments: list[str | None] = []
            for task, gpu_devices in zip(wave_tasks, assignments):
                entry = task["entry"]
                seed = int(task["seed"])
                pkg_dir = _package_dir(workspace_root, default_pkg, entry["tc"])
                env = _eval_env(
                    task_meta=task_meta,
                    out_dir=out_dir,
                    workspace_root=workspace_root,
                    pkg_dir=pkg_dir,
                    tc=entry["tc"],
                    seed=seed,
                )
                budget = _run_budget_check(
                    task_meta=task_meta,
                    workspace_root=workspace_root,
                    pkg_dir=pkg_dir,
                    out_dir=out_dir,
                    label=entry["label"],
                    seed=seed,
                    env=env,
                    effective_test_cmds=test_cmds,
                    eval_root=eval_root,
                )
                if budget and budget["rc"] != 0:
                    records[(entry["idx"], seed)] = _write_error_record(
                        out_dir,
                        entry,
                        seed,
                        f"[BUDGET CHECK FAILED]\nSee {budget['log']}",
                        int(budget["rc"]),
                    )
                    with (out_dir / "budget_violation.txt").open("a") as fh:
                        fh.write(
                            f"{entry['label']} seed {seed} failed budget_check.py; "
                            f"see {budget['log']}\n"
                        )
                    continue
                runnable_tasks.append(task)
                runnable_assignments.append(gpu_devices)

            if not runnable_tasks:
                continue

            # Expose the legacy /workspace/_task path that some eval wrappers
            # reference (humanoid: `python _task/scripts/...`; dllm:
            # `--data-path /workspace/_task/data/...`). Native MLSBench bind-mounts
            # the task dir there, but Harbor has no bind mounts. We point _task at
            # a MINIMAL throwaway copy (scripts/data/third_party only) rather than
            # task_meta, so eval-time agent code (running as root) cannot reach and
            # overwrite the scoring metadata (parser.py/score_spec.py/config.json)
            # before the score phase. The guard exempts the _task top-level dir and
            # runs as a separate pre-eval invocation, so this never affects the diff.
            eval_task_dir = _build_eval_task_dir(task_meta)
            eval_task_links = _install_budget_legacy_links(eval_task_dir, workspace_root)
            try:
                wave_results = _run_eval_wave(
                    tasks=runnable_tasks,
                    assignments=runnable_assignments,
                    task_meta=task_meta,
                    workspace_root=workspace_root,
                    default_pkg=default_pkg,
                    out_dir=out_dir,
                )
            finally:
                _remove_budget_legacy_links(eval_task_links)
                shutil.rmtree(eval_task_dir, ignore_errors=True)
            records.update(wave_results)
            if any(int(r.get("rc", 0) or 0) == 124 for r in wave_results.values()):
                print(
                    f"[wave] a command was killed at its deadline; waiting "
                    f"{WAVE_KILL_SETTLE_SEC}s for its sockets to clear before the next wave",
                    flush=True,
                )
                time.sleep(WAVE_KILL_SETTLE_SEC)
            for task in runnable_tasks:
                entry = task["entry"]
                seed = int(task["seed"])
                if (entry["idx"], seed) not in wave_results:
                    records[(entry["idx"], seed)] = _write_error_record(
                        out_dir,
                        entry,
                        seed,
                        "[ERROR] eval command produced no result",
                        125,
                    )

    for idx, _tc in enumerate(test_cmds):
        for seed in seeds:
            record = records.get((idx, seed))
            if record is not None:
                summary[idx]["logs"].append(record)

    (out_dir / "eval_summary.json").write_text(json.dumps(summary, indent=2))
    return 0


# --------------------------------------------------------------------------- #
# Score: parse logs, aggregate, write reward
# --------------------------------------------------------------------------- #

def _aggregate_metrics(metrics_list: list[dict]) -> dict:
    try:
        from mlsbench.agent.tools import WorkspaceTools  # type: ignore[import-not-found]
        return WorkspaceTools._aggregate_metrics(metrics_list)
    except Exception:
        pass

    if not metrics_list:
        return {}
    if len(metrics_list) == 1:
        return metrics_list[0]

    collected: dict[str, list[float]] = {}
    for metrics in metrics_list:
        for key, value in metrics.items():
            try:
                collected.setdefault(key, []).append(float(value))
            except (TypeError, ValueError):
                pass

    aggregated: dict[str, float] = {}
    for key, values in collected.items():
        finite = [value for value in values if math.isfinite(value)]
        aggregated[key] = sum(finite) / len(finite) if finite else float("nan")
    return aggregated


def _has_real_metrics(record: dict) -> bool:
    for key, value in record.items():
        if (
            key in {"timestamp", "model", "is_final", "seed"}
            or str(key).startswith("elapsed_")
            or str(key).endswith("_std")
        ):
            continue
        if value in ("", None):
            continue
        return True
    return False


def _valid_seed_metric_records(per_seed_metrics: dict[int, dict]) -> list[dict]:
    return [metrics for _seed, metrics in sorted(per_seed_metrics.items()) if _has_real_metrics(metrics)]

def _eval_failures(summary: list[dict], config: dict) -> list[str]:
    """One line per (label, seed) whose eval command did not exit 0.

    rc=124 is this runner's own deadline (the wave's longest ``time`` plus
    WAVE_GRACE_SEC), so say so in words: a reader of ``score_error.txt``
    otherwise sees only "no metrics extracted" and cannot tell a harness
    timeout from a model that produced nothing.
    """
    own_deadline: dict[str, int] = {}
    for tc in _effective_test_cmds(config):
        label = str(tc.get("label", tc.get("cmd", "test")))
        own_deadline[label] = (
            _parse_time_to_seconds(tc.get("time", "1:00:00")) + WAVE_GRACE_SEC
        )
    lines: list[str] = []
    for entry in summary:
        label = str(entry.get("label", ""))
        for log in entry.get("logs", []):
            rc = log.get("rc")
            if rc in (0, None):
                continue
            elapsed = float(log.get("elapsed") or 0.0)
            where = f"{label} seed {log.get('seed')}"
            if rc == 124:
                lines.append(
                    f"{where}: timed out after {elapsed:.0f}s "
                    f"(its own deadline is {own_deadline.get(label, 0)}s incl. "
                    f"{WAVE_GRACE_SEC}s grace; a wave shares its slowest member's)"
                )
            else:
                lines.append(f"{where}: exited rc={rc} after {elapsed:.0f}s")
    return lines


def cmd_score(args: argparse.Namespace) -> int:
    task_meta = Path(args.task_meta)
    out_dir = Path(args.out_dir)
    reward_out = Path(args.reward_out)
    reward_out.parent.mkdir(parents=True, exist_ok=True)

    # mlsbench src ships in the per-task tests/ dir (not in the base image —
    # the agent's shell would see it otherwise). Harbor mounts tests/ at
    # /tests/ only at verify time, so /tests/mlsbench_src is verifier-only.
    sys.path.insert(0, "/tests/mlsbench_src")
    sys.path.insert(0, str(task_meta))
    try:
        # Pre-import & pin every mlsbench module we need INTO sys.modules
        # BEFORE we exec_module the task's parser.py. parser.py itself does
        # `sys.path.insert(0, PROJECT_ROOT / "src")` with PROJECT_ROOT
        # computed from its own __file__; for verifier mode that lands at
        # /tmp/<rand>/src which doesn't exist, but if a future change ever
        # makes it resolve to a real (and possibly different) mlsbench
        # package, the import cache here means parser still picks the
        # version we pinned. (Defense-in-depth against sys.path shadowing.)
        from mlsbench.scoring.evaluate import score_record, load_expanded_spec  # type: ignore[import-not-found]
        from mlsbench.scoring.anchors import BaselineAnchors  # type: ignore[import-not-found]
        import mlsbench.agent.parsers  # ensures the task parser inherits this version

        import __future__
        import types

        # Compile with PEP 563 (postponed annotation evaluation) so a task
        # parser written with PEP 585 generics (``-> tuple[str, dict]``,
        # ``list[float] = []``) also runs on the older container Pythons that
        # cannot subscript builtins at definition time (for example the
        # cleanrl image's Python 3.8).  Native scoring runs the parser in the
        # host's Python, so this difference only shows up inside Harbor.
        parser_path = task_meta / "parser.py"
        task_parser = types.ModuleType("task_parser")
        task_parser.__file__ = str(parser_path)
        code = compile(
            parser_path.read_text(),
            str(parser_path),
            "exec",
            flags=__future__.annotations.compiler_flag,
        )
        exec(code, task_parser.__dict__)
    except Exception as exc:
        reward_out.write_text("0\n")
        (out_dir / "score_error.txt").write_text(f"import failed: {exc}\n")
        return 0

    config = json.loads((task_meta / "config.json").read_text())
    summary_path = out_dir / "eval_summary.json"
    if not summary_path.exists():
        reward_out.write_text("0\n")
        (out_dir / "score_error.txt").write_text("eval_summary.json missing\n")
        return 0
    summary = json.loads(summary_path.read_text())
    failures = _eval_failures(summary, config)
    if failures:
        (out_dir / "eval_failures.txt").write_text("".join(f"{line}\n" for line in failures))

    # Parse every log, aggregate per-seed metrics, then mean across seeds.
    test_cmd_by_label = {tc.get("label", tc["cmd"]): tc for tc in config.get("test_cmds", [])}
    per_seed_metrics: dict[int, dict] = {}
    for entry in summary:
        label = entry["label"]
        tc = test_cmd_by_label.get(label)
        if tc is None:
            continue
        # Every MLS-Bench parser.py defines `class Parser(OutputParser)` with
        # `parse(self, cmd_label, raw_output) -> ParseResult`.
        parser_inst = task_parser.Parser()
        for log_info in entry.get("logs", []):
            if "log" not in log_info:
                continue
            seed = int(log_info["seed"])
            log_path = Path(log_info["log"])
            if not log_path.exists():
                continue
            log_text = log_path.read_text()
            try:
                parsed = parser_inst.parse(label, log_text)
            except Exception as exc:
                with (out_dir / "parse_errors.txt").open("a") as fh:
                    fh.write(f"{label} seed {seed}: {exc}\n")
                continue
            metrics = getattr(parsed, "metrics", None) or {}
            seed_metrics = per_seed_metrics.setdefault(seed, {})
            seed_metrics.update(metrics)
            if "elapsed" in log_info:
                try:
                    seed_metrics[f"elapsed_{label}"] = float(log_info["elapsed"])
                except (TypeError, ValueError):
                    pass

    valid_metrics = _valid_seed_metric_records(per_seed_metrics)
    if not valid_metrics:
        reward_out.write_text("0\n")
        detail = "no metrics extracted from logs\n"
        if failures:
            detail += "eval commands that did not finish cleanly:\n" + "".join(
                f"  {line}\n" for line in failures
            )
        (out_dir / "score_error.txt").write_text(detail)
        return 0

    mean_metrics = _aggregate_metrics(valid_metrics)

    # Score via mlsbench DSL against task's score_spec.py + anchors.
    anchors = BaselineAnchors(task_meta)
    spec = load_expanded_spec(task_meta, anchors)
    if spec is None:
        reward_out.write_text("0\n")
        (out_dir / "score_error.txt").write_text("score_spec missing or invalid\n")
        return 0

    combined = score_record(spec, mean_metrics, anchors)
    # combined_score is meant to be roughly in [0, 1]; clip defensively.
    if combined is None or combined != combined:  # NaN check
        combined = 0.0
    reward = max(0.0, min(1.0, float(combined)))

    reward_out.write_text(f"{reward}\n")
    (out_dir / "metrics.json").write_text(json.dumps({
        "combined_score": combined,
        "reward": reward,
        "eval_failures": failures,
        "mean_metrics": mean_metrics,
        "per_seed_metrics": per_seed_metrics,
    }, indent=2))
    return 0


# --------------------------------------------------------------------------- #
# CLI
# --------------------------------------------------------------------------- #

def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser()
    sub = p.add_subparsers(dest="cmd", required=True)

    g = sub.add_parser("guard")
    g.add_argument("--task-meta", required=True)
    g.add_argument("--pristine", required=True, help="Workdir-level pristine root, e.g. /opt/mlsbench/original")
    g.add_argument("--workspace", required=True, help="Workdir-level workspace root, e.g. /workspace")
    g.add_argument("--violation-out", required=True)
    g.set_defaults(func=cmd_guard)

    r = sub.add_parser("run-evals")
    r.add_argument("--task-meta", required=True)
    r.add_argument("--workspace", required=True, help="Workdir-level workspace root, e.g. /workspace")
    r.add_argument("--eval-root", required=True, help="Dir containing scripts/ — e.g. /tests/eval")
    r.add_argument("--out-dir", required=True)
    r.add_argument("--oracle-cmd-overrides", default=None,
                   help="Oracle-only JSON list of {label, cmd} substitutions.")
    r.set_defaults(func=cmd_run_evals)

    s = sub.add_parser("score")
    s.add_argument("--task-meta", required=True)
    s.add_argument("--out-dir", required=True)
    s.add_argument("--reward-out", required=True)
    s.set_defaults(func=cmd_score)

    args = p.parse_args(argv)
    return args.func(args)


if __name__ == "__main__":
    sys.exit(main())
